import torch
import torch.nn as nn
import numpy as np

def get_phi_mask(out_features, in_features):
    """
    Generates a Golden-Ratio (Phyllotaxis) mask for a weight matrix.
    Only 'packs' weights where nature would place a seed.
    """
    mask = torch.zeros(out_features, in_features)
    phi = (1 + 5**0.5) / 2
    golden_angle = 2 * np.pi * (1 - 1/phi)

    # We treat the weight matrix as a 2D field
    num_seeds = min(out_features, in_features)
    for i in range(num_seeds):
        # Fermat Spiral math: r = sqrt(i), theta = i * golden_angle
        r = np.sqrt(i) / np.sqrt(num_seeds)
        theta = i * golden_angle

        # Map spiral coordinates to matrix indices
        x = int((r * np.cos(theta) * 0.5 + 0.5) * (out_features - 1))
        y = int((r * np.sin(theta) * 0.5 + 0.5) * (in_features - 1))
        mask[x, y] = 1.0

    return mask

class PhiSparseLayer(nn.Module):
    def __init__(self, in_f, out_f):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(out_f, in_f))
        # Register the 'Golden Mask' so it doesn't change
        self.register_buffer('mask', get_phi_mask(out_f, in_f))

    def forward(self, x):
        # We only use the 'Golden' weights
        sparse_weight = self.weight * self.mask
        return torch.matmul(x, sparse_weight.t())

# --- THE EXPERIMENT ---
# Create a tiny model using 90% less 'active' space
model = nn.Sequential(
    PhiSparseLayer(128, 64),
    nn.ReLU(),
    PhiSparseLayer(64, 10)
)

print(f"Total possible weights: {128*64 + 64*10}")
print(f"Active 'Golden' weights: {int(model[0].mask.sum() + model[2].mask.sum())}")

import torch
import torch.nn as nn
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import numpy as np
import matplotlib.pyplot as plt
import pandas as pd
from tqdm import tqdm

# ====================== PHI MASK (your original genius) ======================
def get_phi_mask(out_features, in_features, density=0.05):
    """Your phyllotaxis mask — now with adjustable density"""
    mask = torch.zeros(out_features, in_features)
    phi = (1 + 5**0.5) / 2
    golden_angle = 2 * np.pi * (1 - 1/phi)
    num_seeds = int(density * out_features * in_features)
    for i in range(num_seeds):
        r = np.sqrt(i) / np.sqrt(num_seeds)
        theta = i * golden_angle
        x = int((r * np.cos(theta) * 0.5 + 0.5) * (out_features - 1))
        y = int((r * np.sin(theta) * 0.5 + 0.5) * (in_features - 1))
        if 0 <= x < out_features and 0 <= y < in_features:
            mask[x, y] = 1.0
    return mask

class PhiSparseLayer(nn.Module):
    def __init__(self, in_f, out_f, density=0.05):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(out_f, in_f) * 0.1)
        self.register_buffer('mask', get_phi_mask(out_f, in_f, density))

    def forward(self, x):
        sparse_weight = self.weight * self.mask
        return torch.matmul(x, sparse_weight.t())

# ====================== RANDOM SPARSE (for fair comparison) ======================
class RandomSparseLayer(nn.Module):
    def __init__(self, in_f, out_f, density=0.05):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(out_f, in_f) * 0.1)
        mask = torch.zeros(out_f, in_f)
        num_active = int(density * out_f * in_f)
        indices = torch.randperm(out_f * in_f)[:num_active]
        mask.view(-1)[indices] = 1.0
        self.register_buffer('mask', mask)

    def forward(self, x):
        return torch.matmul(x, (self.weight * self.mask).t())

# ====================== TRAINING SETUP ======================
transform = transforms.Compose([transforms.ToTensor(), transforms.Normalize((0.1307,), (0.3081,))])
trainset = torchvision.datasets.MNIST(root='./data', train=True, download=True, transform=transform)
trainloader = torch.utils.data.DataLoader(trainset, batch_size=128, shuffle=True)

def train_model(model, name, epochs=5):
    optimizer = optim.Adam(model.parameters(), lr=0.001)
    criterion = nn.CrossEntropyLoss()
    accuracies = []
    for epoch in range(epochs):
        correct = 0
        total = 0
        for data in tqdm(trainloader, desc=f"{name} Epoch {epoch+1}"):
            inputs, labels = data
            optimizer.zero_grad()
            outputs = model(inputs.view(-1, 28*28))
            loss = criterion(outputs, labels)
            loss.backward()
            optimizer.step()

            _, predicted = outputs.max(1)
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
        acc = 100 * correct / total
        accuracies.append(acc)
        print(f"  {name} Epoch {epoch+1}: {acc:.2f}%")
    return accuracies

# ====================== RUN THE EXPERIMENT ======================
density = 0.05  # change this to experiment (0.01 = ultra sparse, 0.10 = denser)

print("🚀 Starting Phyllotactic Sparsity experiment...")

# Models
phi_model = nn.Sequential(
    PhiSparseLayer(784, 256, density),
    nn.ReLU(),
    PhiSparseLayer(256, 128, density),
    nn.ReLU(),
    PhiSparseLayer(128, 10, density)
)

random_model = nn.Sequential(
    RandomSparseLayer(784, 256, density),
    nn.ReLU(),
    RandomSparseLayer(256, 128, density),
    nn.ReLU(),
    RandomSparseLayer(128, 10, density)
)

dense_model = nn.Sequential(
    nn.Linear(784, 256),
    nn.ReLU(),
    nn.Linear(256, 128),
    nn.ReLU(),
    nn.Linear(128, 10)
)

# Train all three
phi_acc = train_model(phi_model, "🌻 Golden Spiral")
random_acc = train_model(random_model, "🎲 Random Sparse")
dense_acc = train_model(dense_model, "📏 Dense")

# Save results for your post/paper
results = pd.DataFrame({
    "Epoch": range(1, len(phi_acc)+1),
    "Golden_Spiral_Acc": phi_acc,
    "Random_Sparse_Acc": random_acc,
    "Dense_Acc": dense_acc
})
results.to_csv("phyllotactic_results.csv", index=False)
print("\n💾 Saved 'phyllotactic_results.csv' — perfect for your X thread or paper!")

# Quick plot of masks (visual proof it looks like a sunflower)
