# =========================
# Colab-ready experiment
# Phyllotactic Sparsity vs Random Sparsity vs Dense
# =========================

import math
import random
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

from tqdm.auto import tqdm
from torch.utils.data import DataLoader

# -------------------------
# Reproducibility
# -------------------------
def seed_everything(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -------------------------
# Mask generators
# -------------------------
def phyllotaxis_mask(out_features: int, in_features: int, density: float = 0.05):
    """
    Fixed golden-angle / Fermat spiral mask.
    Keeps exactly round(density * out_features * in_features) active weights.
    """
    total = out_features * in_features
    k = max(1, int(round(total * density)))

    mask = torch.zeros(out_features, in_features, dtype=torch.float32)

    phi = (1 + 5 ** 0.5) / 2
    golden_angle = 2 * np.pi * (1 - 1 / phi)

    used = set()
    i = 0
    max_iter = total * 10

    while len(used) < k and i < max_iter:
        r = np.sqrt(i / max(1, k))
        theta = i * golden_angle

        x = (0.5 + 0.5 * r * np.cos(theta)) * (out_features - 1)
        y = (0.5 + 0.5 * r * np.sin(theta)) * (in_features - 1)

        xi = int(np.clip(np.round(x), 0, out_features - 1))
        yi = int(np.clip(np.round(y), 0, in_features - 1))

        if (xi, yi) not in used:
            used.add((xi, yi))
            mask[xi, yi] = 1.0

        i += 1

    if len(used) < k:
        for x in range(out_features):
            for y in range(in_features):
                if len(used) >= k:
                    break
                if (x, y) not in used:
                    used.add((x, y))
                    mask[x, y] = 1.0
            if len(used) >= k:
                break

    return mask

def random_mask(out_features: int, in_features: int, density: float = 0.05, generator=None):
    """
    Exact same active count as phyllotaxis_mask.
    """
    total = out_features * in_features
    k = max(1, int(round(total * density)))

    mask = torch.zeros(total, dtype=torch.float32)
    idx = torch.randperm(total, generator=generator)[:k]
    mask[idx] = 1.0
    return mask.view(out_features, in_features)

# -------------------------
# Layers
# -------------------------
class MaskedLinear(nn.Module):
    def __init__(self, in_f, out_f, mask, bias=True):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(out_f, in_f))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_f))
        else:
            self.bias = None

        self.register_buffer("mask", mask.float())

    def forward(self, x):
        return F.linear(x, self.weight * self.mask, self.bias)

# -------------------------
# Models
# -------------------------
class MLPMasked(nn.Module):
    def __init__(self, mask_kind="phi", density=0.05, seed=0):
        super().__init__()
        gen = torch.Generator().manual_seed(seed)

        if mask_kind == "phi":
            m1 = phyllotaxis_mask(256, 784, density)
            m2 = phyllotaxis_mask(128, 256, density)
            m3 = phyllotaxis_mask(10, 128, density)
        elif mask_kind == "random":
            m1 = random_mask(256, 784, density, generator=gen)
            m2 = random_mask(128, 256, density, generator=gen)
            m3 = random_mask(10, 128, density, generator=gen)
        else:
            raise ValueError("mask_kind must be 'phi' or 'random'")

        self.net = nn.Sequential(
            MaskedLinear(784, 256, m1, bias=True),
            nn.ReLU(),
            MaskedLinear(256, 128, m2, bias=True),
            nn.ReLU(),
            MaskedLinear(128, 10, m3, bias=True),
        )

    def forward(self, x):
        return self.net(x)

class MLPDense(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(784, 256, bias=True),
            nn.ReLU(),
            nn.Linear(256, 128, bias=True),
            nn.ReLU(),
            nn.Linear(128, 10, bias=True),
        )

    def forward(self, x):
        return self.net(x)

# -------------------------
# Counting
# -------------------------
def count_report(model):
    total_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    active_params = 0
    total_possible = 0

    for m in model.modules():
        if isinstance(m, MaskedLinear):
            total_possible += m.weight.numel()
            active_params += int(m.mask.sum().item())
            if m.bias is not None:
                total_possible += m.bias.numel()
                active_params += m.bias.numel()
        elif isinstance(m, nn.Linear):
            total_possible += m.weight.numel()
            active_params += m.weight.numel()
            if m.bias is not None:
                total_possible += m.bias.numel()
                active_params += m.bias.numel()

    return {
        "trainable_params": total_params,
        "active_params_in_forward": active_params,
        "total_possible_params": total_possible,
    }

# -------------------------
# Data
# -------------------------
transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize((0.1307,), (0.3081,))
])

trainset = torchvision.datasets.MNIST(root="./data", train=True, download=True, transform=transform)
testset = torchvision.datasets.MNIST(root="./data", train=False, download=True, transform=transform)

# IMPORTANT: num_workers=0 fixes the multiprocessing cleanup error on CPU/Colab
train_loader = DataLoader(trainset, batch_size=128, shuffle=True, num_workers=0, pin_memory=False)
test_loader = DataLoader(testset, batch_size=256, shuffle=False, num_workers=0, pin_memory=False)

# -------------------------
# Train / eval
# -------------------------
def evaluate(model, loader, device, noise_sigma=0.0):
    model.eval()
    criterion = nn.CrossEntropyLoss()

    total_loss = 0.0
    correct = 0
    total = 0

    with torch.no_grad():
        for x, y in loader:
            x = x.to(device)
            y = y.to(device)

            if noise_sigma > 0:
                x = x + noise_sigma * torch.randn_like(x)

            x = x.view(x.size(0), -1)
            logits = model(x)
            loss = criterion(logits, y)

            total_loss += loss.item() * y.size(0)
            pred = logits.argmax(dim=1)
            correct += (pred == y).sum().item()
            total += y.size(0)

    return total_loss / total, 100.0 * correct / total

def train_model(model, train_loader, test_loader, device, epochs=5, lr=1e-3, noise_sigma=0.0, name="model"):
    model.to(device)
    optimizer = optim.Adam(model.parameters(), lr=lr)
    criterion = nn.CrossEntropyLoss()

    history = []

    for epoch in range(1, epochs + 1):
        model.train()
        running_loss = 0.0
        correct = 0
        total = 0

        pbar = tqdm(train_loader, desc=f"{name} | Epoch {epoch}/{epochs}", leave=False)
        for x, y in pbar:
            x = x.to(device)
            y = y.to(device)
            x = x.view(x.size(0), -1)

            optimizer.zero_grad()
            logits = model(x)
            loss = criterion(logits, y)
            loss.backward()
            optimizer.step()

            running_loss += loss.item() * y.size(0)
            pred = logits.argmax(dim=1)
            correct += (pred == y).sum().item()
            total += y.size(0)

            pbar.set_postfix(train_acc=f"{100.0 * correct / total:.2f}%")

        train_loss = running_loss / total
        train_acc = 100.0 * correct / total
        test_loss, test_acc = evaluate(model, test_loader, device, noise_sigma=0.0)
        noisy_loss, noisy_acc = evaluate(model, test_loader, device, noise_sigma=noise_sigma)

        row = {
            "epoch": epoch,
            "train_loss": train_loss,
            "train_acc": train_acc,
            "test_loss": test_loss,
            "test_acc": test_acc,
            "noisy_test_loss": noisy_loss,
            "noisy_test_acc": noisy_acc,
        }
        history.append(row)

        print(
            f"{name} | epoch {epoch:02d} | "
            f"train {train_acc:.2f}% | test {test_acc:.2f}% | noisy {noisy_acc:.2f}%"
        )

    return pd.DataFrame(history)

# -------------------------
# Experiment runner
# -------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

DENSITY = 0.05
EPOCHS = 5
SEEDS = [0, 1, 2, 3, 4]
NOISE_SIGMA = 0.20

all_rows = []
summary_rows = []

print("Device:", device)
print("Starting experiment...")

for seed in SEEDS:
    print(f"\n===== SEED {seed} =====")
    seed_everything(seed)

    seed_everything(seed)
    phi_model = MLPMasked(mask_kind="phi", density=DENSITY, seed=seed)

    seed_everything(seed)
    random_model = MLPMasked(mask_kind="random", density=DENSITY, seed=seed)

    seed_everything(seed)
    dense_model = MLPDense()

    phi_counts = count_report(phi_model)
    rnd_counts = count_report(random_model)
    dense_counts = count_report(dense_model)

    print("Phi counts:", phi_counts)
    print("Rnd counts:", rnd_counts)
    print("Dense counts:", dense_counts)

    phi_hist = train_model(phi_model, train_loader, test_loader, device, epochs=EPOCHS, lr=1e-3, noise_sigma=NOISE_SIGMA, name=f"PHI   seed={seed}")
    rnd_hist = train_model(random_model, train_loader, test_loader, device, epochs=EPOCHS, lr=1e-3, noise_sigma=NOISE_SIGMA, name=f"RAND  seed={seed}")
    dense_hist = train_model(dense_model, train_loader, test_loader, device, epochs=EPOCHS, lr=1e-3, noise_sigma=NOISE_SIGMA, name=f"DENSE seed={seed}")

    phi_hist["model"] = "phi"
    rnd_hist["model"] = "random"
    dense_hist["model"] = "dense"

    phi_hist["seed"] = seed
    rnd_hist["seed"] = seed
    dense_hist["seed"] = seed

    all_rows.append(phi_hist)
    all_rows.append(rnd_hist)
    all_rows.append(dense_hist)

    summary_rows.append({
        "seed": seed,
        "phi_final_test_acc": float(phi_hist["test_acc"].iloc[-1]),
        "random_final_test_acc": float(rnd_hist["test_acc"].iloc[-1]),
        "dense_final_test_acc": float(dense_hist["test_acc"].iloc[-1]),
        "phi_final_noisy_acc": float(phi_hist["noisy_test_acc"].iloc[-1]),
        "random_final_noisy_acc": float(rnd_hist["noisy_test_acc"].iloc[-1]),
        "dense_final_noisy_acc": float(dense_hist["noisy_test_acc"].iloc[-1]),
        "phi_active_params": phi_counts["active_params_in_forward"],
        "random_active_params": rnd_counts["active_params_in_forward"],
        "dense_active_params": dense_counts["active_params_in_forward"],
    })

# -------------------------
# Save results
# -------------------------
results = pd.concat(all_rows, ignore_index=True)
summary = pd.DataFrame(summary_rows)

results.to_csv("phyllotactic_all_epochs.csv", index=False)
summary.to_csv("phyllotactic_summary_by_seed.csv", index=False)

print("\nSaved:")
print(" - phyllotactic_all_epochs.csv")
print(" - phyllotactic_summary_by_seed.csv")

# -------------------------
# Final aggregate report
# -------------------------
finals = results.groupby("model").tail(1).copy()
final_summary = finals.groupby("model").agg(
    mean_test_acc=("test_acc", "mean"),
    std_test_acc=("test_acc", "std"),
    mean_noisy_acc=("noisy_test_acc", "mean"),
    std_noisy_acc=("noisy_test_acc", "std"),
).reset_index()

print("\n===== FINAL SUMMARY (mean over seeds, final epoch) =====")
print(final_summary)

# -------------------------
# Plot
# -------------------------
plt.figure(figsize=(10, 6))
for model_name in ["phi", "random", "dense"]:
    subset = results[results["model"] == model_name]
    by_epoch = subset.groupby("epoch")["test_acc"].agg(["mean", "std"])
    plt.plot(by_epoch.index, by_epoch["mean"], label=f"{model_name} test acc")
