"""Current result already says phi > random, but it does not yet prove the golden angle itself is the reason. A reviewer will immediately ask: “Would any spiral-like pattern do the same?” So the cleanest next experiment is:

same model, same density, same seeds, only change the angle

Compare:

golden angle
90°
180°
a few irrational angles
random angle

If golden angle still wins, your core idea gets much stronger.
"""

# =========================
# FULL ANGLE ABLATION EXPERIMENT (FINAL)
# =========================

import math
import random
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

from tqdm.auto import tqdm
from torch.utils.data import DataLoader

# -------------------------
# Reproducibility
# -------------------------
def seed_everything(seed):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -------------------------
# Device
# -------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

if device.type == "cuda":
    print("🔥 GPU:", torch.cuda.get_device_name(0))
else:
    print("⚠️ Running on CPU")

# -------------------------
# Angle function
# -------------------------
def angle_from_name(name, seed):
    phi = (1 + 5 ** 0.5) / 2
    golden = 2 * np.pi * (1 - 1 / phi)

    if name == "golden":
        return golden
    elif name == "deg90":
        return np.pi / 2
    elif name == "deg180":
        return np.pi
    elif name == "pi":
        return np.pi
    elif name == "e":
        return np.e
    elif name == "sqrt2":
        return np.sqrt(2)
    elif name == "random_angle":
        rng = np.random.default_rng(seed)
        return float(rng.uniform(0.1, 2*np.pi - 0.1))
    else:
        return None

# -------------------------
# Mask generators
# -------------------------
def spiral_mask(out_f, in_f, density, theta):
    total = out_f * in_f
    k = int(total * density)

    i = np.arange(k * 3)  # oversample
    r = np.sqrt(i / k)
    t = i * theta

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(int)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(int)

    coords = list(set(zip(xi, yi)))[:k]

    mask = torch.zeros(out_f, in_f)
    for x, y in coords:
        mask[x, y] = 1.0

    return mask

def random_mask(out_f, in_f, density, gen):
    total = out_f * in_f
    k = int(total * density)

    mask = torch.zeros(total)
    idx = torch.randperm(total, generator=gen)[:k]
    mask[idx] = 1
    return mask.view(out_f, in_f)

# -------------------------
# Layer
# -------------------------
class MaskedLinear(nn.Module):
    def __init__(self, in_f, out_f, mask):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(out_f, in_f))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_f))
        self.register_buffer("mask", mask)

    def forward(self, x):
        return F.linear(x, self.weight * self.mask, self.bias)

# -------------------------
# Models
# -------------------------
class SparseModel(nn.Module):
    def __init__(self, mode, seed):
        super().__init__()
        gen = torch.Generator().manual_seed(seed)

        if mode == "random_sparse":
            m1 = random_mask(256, 784, 0.05, gen)
            m2 = random_mask(128, 256, 0.05, gen)
            m3 = random_mask(10, 128, 0.05, gen)
        else:
            theta = angle_from_name(mode, seed)
            m1 = spiral_mask(256, 784, 0.05, theta)
            m2 = spiral_mask(128, 256, 0.05, theta)
            m3 = spiral_mask(10, 128, 0.05, theta)

        self.net = nn.Sequential(
            MaskedLinear(784,256,m1),
            nn.ReLU(),
            MaskedLinear(256,128,m2),
            nn.ReLU(),
            MaskedLinear(128,10,m3),
        )

    def forward(self,x):
        return self.net(x)

class DenseModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(784,256),
            nn.ReLU(),
            nn.Linear(256,128),
            nn.ReLU(),
            nn.Linear(128,10),
        )
    def forward(self,x):
        return self.net(x)

# -------------------------
# Data
# -------------------------
transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize((0.1307,), (0.3081,))
])

trainset = torchvision.datasets.MNIST("./data", train=True, download=True, transform=transform)
testset = torchvision.datasets.MNIST("./data", train=False, download=True, transform=transform)

train_loader = DataLoader(trainset, batch_size=128, shuffle=True, num_workers=0, pin_memory=True)
test_loader = DataLoader(testset, batch_size=256, shuffle=False, num_workers=0, pin_memory=True)

# -------------------------
# Train / Eval
# -------------------------
def evaluate(model):
    model.eval()
    correct=0; total=0

    with torch.no_grad():
        for x,y in test_loader:
            x,y = x.to(device), y.to(device)
            x = x.view(x.size(0), -1)
            pred = model(x).argmax(1)
            correct += (pred==y).sum().item()
            total += y.size(0)

    return 100*correct/total

def train(model, name):
    model.to(device)
    opt = optim.Adam(model.parameters(), lr=1e-3)
    loss_fn = nn.CrossEntropyLoss()

    for epoch in range(5):
        model.train()

        pbar = tqdm(train_loader, desc=f"{name} | Epoch {epoch+1}")

        correct=0; total=0

        for x,y in pbar:
            x,y = x.to(device), y.to(device)
            x = x.view(x.size(0), -1)

            opt.zero_grad()
            logits = model(x)
            loss = loss_fn(logits,y)
            loss.backward()
            opt.step()

            pred = logits.argmax(1)
            correct += (pred==y).sum().item()
            total += y.size(0)

            pbar.set_postfix(acc=f"{100*correct/total:.2f}%")

        acc = evaluate(model)
        print(f"✅ {name} epoch {epoch+1} test={acc:.2f}%")

    return acc

# -------------------------
# Experiment
# -------------------------
ANGLES = ["golden","deg90","deg180","pi","e","sqrt2","random_angle","random_sparse","dense"]
SEEDS = [0,1,2,3,4]

results = []

for seed in SEEDS:
    print(f"\n===== SEED {seed} =====")
    seed_everything(seed)

    for name in ANGLES:
        print(f"\n🚀 Starting model: {name} (seed {seed})")
        seed_everything(seed)

        if name == "dense":
            model = DenseModel()
        else:
            model = SparseModel(name, seed)

        acc = train(model, name)

        results.append({
            "seed":seed,
            "model":name,
            "acc":acc
        })

# -------------------------
# Summary
# -------------------------
df = pd.DataFrame(results)

summary = df.groupby("model")["acc"].agg(["mean","std"]).reset_index()
summary = summary.sort_values("mean", ascending=False)

print("\n===== FINAL RESULT =====")
print(summary)

# -------------------------
# Plot
# -------------------------
plt.figure(figsize=(10,5))
for m in summary["model"]:
    vals = df[df["model"]==m]["acc"]
    plt.scatter([m]*len(vals), vals)

plt.xticks(rotation=45)
plt.ylabel("Accuracy")
plt.title("Angle Ablation Results")
plt.tight_layout()
plt.show()

