# =========================
# FASHION-MNIST: FULL ANGLE ABLATION EXPERIMENT
# =========================

import math
import random
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

from tqdm.auto import tqdm
from torch.utils.data import DataLoader

# -------------------------
# Reproducibility
# -------------------------
def seed_everything(seed):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -------------------------
# Device
# -------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

if device.type == "cuda":
    print("🔥 GPU:", torch.cuda.get_device_name(0))
else:
    print("⚠️ Running on CPU")

# -------------------------
# Angle function
# -------------------------
def angle_from_name(name, seed):
    phi = (1 + 5 ** 0.5) / 2
    golden = 2 * np.pi * (1 - 1 / phi)

    if name == "golden":
        return golden
    elif name == "deg90":
        return np.pi / 2
    elif name in ["deg180", "pi"]:
        return np.pi
    elif name == "e":
        return np.e
    elif name == "sqrt2":
        return np.sqrt(2)
    elif name == "random_angle":
        rng = np.random.default_rng(seed)
        return float(rng.uniform(0.1, 2*np.pi - 0.1))
    else:
        return None

# -------------------------
# Mask generators
# -------------------------
def spiral_mask(out_f, in_f, density, theta):
    total = out_f * in_f
    k = int(total * density)

    i = np.arange(k * 3)  # oversample to handle collisions
    r = np.sqrt(i / k)
    t = i * theta

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(int)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(int)

    coords = list(set(zip(xi, yi)))[:k]

    mask = torch.zeros(out_f, in_f)
    for x, y in coords:
        mask[x, y] = 1.0

    return mask

def random_mask(out_f, in_f, density, gen):
    total = out_f * in_f
    k = int(total * density)

    mask = torch.zeros(total)
    idx = torch.randperm(total, generator=gen)[:k]
    mask[idx] = 1
    return mask.view(out_f, in_f)

# -------------------------
# Layer & Models
# -------------------------
class MaskedLinear(nn.Module):
    def __init__(self, in_f, out_f, mask):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(out_f, in_f))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_f))
        self.register_buffer("mask", mask)

    def forward(self, x):
        return F.linear(x, self.weight * self.mask, self.bias)

class SparseModel(nn.Module):
    def __init__(self, mode, seed):
        super().__init__()
        gen = torch.Generator().manual_seed(seed)

        if mode == "random_sparse":
            m1 = random_mask(256, 784, 0.05, gen)
            m2 = random_mask(128, 256, 0.05, gen)
            m3 = random_mask(10, 128, 0.05, gen)
        else:
            theta = angle_from_name(mode, seed)
            m1 = spiral_mask(256, 784, 0.05, theta)
            m2 = spiral_mask(128, 256, 0.05, theta)
            m3 = spiral_mask(10, 128, 0.05, theta)

        self.net = nn.Sequential(
            MaskedLinear(784,256,m1), nn.ReLU(),
            MaskedLinear(256,128,m2), nn.ReLU(),
            MaskedLinear(128,10,m3)
        )

    def forward(self,x):
        return self.net(x)

class DenseModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(784,256), nn.ReLU(),
            nn.Linear(256,128), nn.ReLU(),
            nn.Linear(128,10)
        )
    def forward(self,x):
        return self.net(x)

# -------------------------
# Data (Fashion-MNIST Update)
# -------------------------
# Fashion-MNIST mean/std are approx 0.2860 and 0.3530
transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize((0.2860,), (0.3530,))
])

# Downloading FashionMNIST instead of MNIST
trainset = torchvision.datasets.FashionMNIST("./data", train=True, download=True, transform=transform)
testset = torchvision.datasets.FashionMNIST("./data", train=False, download=True, transform=transform)

train_loader = DataLoader(trainset, batch_size=128, shuffle=True, num_workers=0, pin_memory=True)
test_loader = DataLoader(testset, batch_size=256, shuffle=False, num_workers=0, pin_memory=True)

# -------------------------
# Train / Eval
# -------------------------
def evaluate(model):
    model.eval()
    correct=0; total=0
    with torch.no_grad():
        for x,y in test_loader:
            x,y = x.to(device), y.to(device)
            x = x.view(x.size(0), -1)
            pred = model(x).argmax(1)
            correct += (pred==y).sum().item()
            total += y.size(0)
    return 100*correct/total

def train(model, name):
    model.to(device)
    opt = optim.Adam(model.parameters(), lr=1e-3)
    loss_fn = nn.CrossEntropyLoss()

    for epoch in range(5):
        model.train()
        pbar = tqdm(train_loader, desc=f"{name} | Epoch {epoch+1}")
        correct=0; total=0

        for x,y in pbar:
            x,y = x.to(device), y.to(device)
            x = x.view(x.size(0), -1)
            opt.zero_grad()
            logits = model(x)
            loss = loss_fn(logits,y)
            loss.backward()
            opt.step()

            pred = logits.argmax(1)
            correct += (pred==y).sum().item()
            total += y.size(0)
            pbar.set_postfix(acc=f"{100*correct/total:.2f}%")

    acc = evaluate(model)
    print(f"✅ {name} Final Test Acc={acc:.2f}%")
    return acc

# -------------------------
# Experiment Run
# -------------------------
ANGLES = ["golden","deg90","pi","e","sqrt2","random_angle","random_sparse","dense"]
SEEDS = [0,1,2,3,4]

results = []

for seed in SEEDS:
    print(f"\n===== SEED {seed} =====")
    for name in ANGLES:
        print(f"\n🚀 Fashion-MNIST Model: {name} (seed {seed})")
        seed_everything(seed)
        model = DenseModel() if name == "dense" else SparseModel(name, seed)
        acc = train(model, name)
        results.append({"seed":seed, "model":name, "acc":acc})

# -------------------------
# Results
# -------------------------
df = pd.DataFrame(results)
summary = df.groupby("model")["acc"].agg(["mean","std"]).reset_index().sort_values("mean", ascending=False)

print("\n===== FASHION-MNIST FINAL RESULT =====")
print(summary)

# Plotting
plt.figure(figsize=(10,5))
for m in summary["model"]:
    vals = df[df["model"]==m]["acc"]
    plt.scatter([m]*len(vals), vals)
plt.xticks(rotation=45)
plt.ylabel("Accuracy (%)")
plt.title("Fashion-MNIST Angle Ablation")
plt.tight_layout()
plt.show()

# =========================
# Density Sweep Experiment
# MNIST + Fashion-MNIST
# golden vs random_sparse
# =========================

import math
import random
import time
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

from tqdm.auto import tqdm
from torch.utils.data import DataLoader

# -------------------------
# Reproducibility
# -------------------------
def seed_everything(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False

# -------------------------
# Device
# -------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)
if device.type == "cuda":
    print("🔥 GPU:", torch.cuda.get_device_name(0))
else:
    print("⚠️ Running on CPU")

# -------------------------
# Configuration
# -------------------------
DATASETS = ["MNIST", "FashionMNIST"]
MODES = ["golden", "random_sparse"]
DENSITIES = [0.01, 0.02, 0.05, 0.10]
SEEDS = [0, 1, 2, 3, 4]
EPOCHS = 5
BATCH_SIZE_TRAIN = 128
BATCH_SIZE_TEST = 256

# -------------------------
# Dataset helpers
# -------------------------
DATASET_STATS = {
    "MNIST": ((0.1307,), (0.3081,)),
    "FashionMNIST": ((0.2860,), (0.3530,))
}

def make_loaders(dataset_name: str):
    mean, std = DATASET_STATS[dataset_name]
    transform = transforms.Compose([
        transforms.ToTensor(),
        transforms.Normalize(mean, std),
    ])

    if dataset_name == "MNIST":
        trainset = torchvision.datasets.MNIST("./data", train=True, download=True, transform=transform)
        testset = torchvision.datasets.MNIST("./data", train=False, download=True, transform=transform)
    elif dataset_name == "FashionMNIST":
        trainset = torchvision.datasets.FashionMNIST("./data", train=True, download=True, transform=transform)
        testset = torchvision.datasets.FashionMNIST("./data", train=False, download=True, transform=transform)
    else:
        raise ValueError(f"Unknown dataset: {dataset_name}")

    pin = device.type == "cuda"
    train_loader = DataLoader(
        trainset,
        batch_size=BATCH_SIZE_TRAIN,
        shuffle=True,
        num_workers=0,
        pin_memory=pin,
    )
    test_loader = DataLoader(
        testset,
        batch_size=BATCH_SIZE_TEST,
        shuffle=False,
        num_workers=0,
        pin_memory=pin,
    )
    return train_loader, test_loader

# -------------------------
# Angle / mask helpers
# -------------------------
def golden_angle():
    phi = (1 + 5 ** 0.5) / 2
    return 2 * np.pi * (1 - 1 / phi)

def spiral_mask(out_f: int, in_f: int, density: float, theta_step: float):
    """
    Fast deterministic spiral mask with exact active count.
    """
    total = out_f * in_f
    k = max(1, int(round(total * density)))

    # Oversample so we can deduplicate and still keep enough points
    n = max(k * 4, k + 32)
    i = np.arange(n, dtype=np.float64)

    r = np.sqrt(i / max(1, k))
    t = i * theta_step

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(np.int64)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(np.int64)

    coords = list(dict.fromkeys(zip(xi.tolist(), yi.tolist())))  # unique, preserve order
    coords = coords[:k]

    mask = torch.zeros(out_f, in_f, dtype=torch.float32)
    for a, b in coords:
        mask[a, b] = 1.0

    # Fallback fill if rare collisions left us short
    if int(mask.sum().item()) < k:
        for a in range(out_f):
            for b in range(in_f):
                if int(mask.sum().item()) >= k:
                    break
                if mask[a, b].item() == 0:
                    mask[a, b] = 1.0
            if int(mask.sum().item()) >= k:
                break

    return mask

def random_mask(out_f: int, in_f: int, density: float, gen: torch.Generator):
    total = out_f * in_f
    k = max(1, int(round(total * density)))
    mask = torch.zeros(total, dtype=torch.float32)
    idx = torch.randperm(total, generator=gen)[:k]
    mask[idx] = 1.0
    return mask.view(out_f, in_f)

# -------------------------
# Layers / models
# -------------------------
class MaskedLinear(nn.Module):
    def __init__(self, in_f, out_f, mask):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(out_f, in_f))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_f))
        self.register_buffer("mask", mask.float())

    def forward(self, x):
        return F.linear(x, self.weight * self.mask, self.bias)

class SparseMLP(nn.Module):
    def __init__(self, mode: str, density: float, seed: int):
        super().__init__()
        gen = torch.Generator().manual_seed(seed)

        if mode == "golden":
            theta = golden_angle()
            m1 = spiral_mask(256, 784, density, theta)
            m2 = spiral_mask(128, 256, density, theta)
            m3 = spiral_mask(10, 128, density, theta)
        elif mode == "random_sparse":
            m1 = random_mask(256, 784, density, gen)
            m2 = random_mask(128, 256, density, gen)
            m3 = random_mask(10, 128, density, gen)
        else:
            raise ValueError(f"Unknown mode: {mode}")

        self.net = nn.Sequential(
            MaskedLinear(784, 256, m1),
            nn.ReLU(),
            MaskedLinear(256, 128, m2),
            nn.ReLU(),
            MaskedLinear(128, 10, m3),
        )

    def forward(self, x):
        return self.net(x)

# -------------------------
# Train / eval
# -------------------------
def evaluate(model, loader):
    model.eval()
    correct = 0
    total = 0
    with torch.no_grad():
        for x, y in loader:
            x = x.to(device, non_blocking=True)
            y = y.to(device, non_blocking=True)
            x = x.view(x.size(0), -1)
            logits = model(x)
            pred = logits.argmax(dim=1)
            correct += (pred == y).sum().item()
            total += y.size(0)
    return 100.0 * correct / total

def train_one(model, train_loader, test_loader, dataset_name, mode, density, seed, epochs=5):
    model.to(device)
    optimizer = optim.Adam(model.parameters(), lr=1e-3)
    criterion = nn.CrossEntropyLoss()

    history = []

    for epoch in range(1, epochs + 1):
        model.train()
        running_correct = 0
        running_total = 0

        pbar = tqdm(
            train_loader,
            desc=f"{dataset_name} | {mode} | d={density:.2%} | seed={seed} | Epoch {epoch}/{epochs}",
            leave=False,
        )

        for x, y in pbar:
            x = x.to(device, non_blocking=True)
            y = y.to(device, non_blocking=True)
            x = x.view(x.size(0), -1)

            optimizer.zero_grad(set_to_none=True)
            logits = model(x)
            loss = criterion(logits, y)
            loss.backward()
            optimizer.step()

            pred = logits.argmax(dim=1)
            running_correct += (pred == y).sum().item()
            running_total += y.size(0)

            pbar.set_postfix(train_acc=f"{100.0 * running_correct / running_total:.2f}%")

        test_acc = evaluate(model, test_loader)
        history.append(test_acc)
        print(f"✅ {dataset_name} | {mode} | d={density:.2%} | seed={seed} | epoch {epoch} | test={test_acc:.2f}%")

    return history

# -------------------------
# Main experiment
# -------------------------
all_rows = []

start_time = time.time()
print("\nStarting density sweep...")

for dataset_name in DATASETS:
    train_loader, test_loader = make_loaders(dataset_name)

    for density in DENSITIES:
        for seed in SEEDS:
            seed_everything(seed)

            for mode in MODES:
                print(f"\n🚀 {dataset_name} | {mode} | density={density:.2%} | seed={seed}")

                seed_everything(seed)
                model = SparseMLP(mode=mode, density=density, seed=seed)

                history = train_one(
                    model=model,
                    train_loader=train_loader,
                    test_loader=test_loader,
                    dataset_name=dataset_name,
                    mode=mode,
                    density=density,
                    seed=seed,
                    epochs=EPOCHS,
                )

                all_rows.append({
                    "dataset": dataset_name,
                    "density": density,
                    "seed": seed,
                    "model": mode,
                    "final_test_acc": float(history[-1]),
                    "best_test_acc": float(max(history)),
                    "epoch_1_acc": float(history[0]),
                    "epoch_5_acc": float(history[-1]),
                })

results = pd.DataFrame(all_rows)
results.to_csv("density_sweep_results.csv", index=False)

print("\nSaved: density_sweep_results.csv")

# -------------------------
# Summary
# -------------------------
summary = (
    results
    .groupby(["dataset", "density", "model"])["final_test_acc"]
    .agg(["mean", "std"])
    .reset_index()
    .sort_values(["dataset", "density", "model"])
)

print("\n===== FINAL SUMMARY =====")
print(summary)

summary.to_csv("density_sweep_summary.csv", index=False)

# -------------------------
# Extra comparison table: golden minus random_sparse
# -------------------------
pivot = summary.pivot_table(
    index=["dataset", "density"],
    columns="model",
    values="mean"
).reset_index()

if "golden" in pivot.columns and "random_sparse" in pivot.columns:
    pivot["golden_minus_random"] = pivot["golden"] - pivot["random_sparse"]

print("\n===== GOLDEN - RANDOM_SPARSE =====")
cols = ["dataset", "density", "golden", "random_sparse", "golden_minus_random"]
print(pivot[cols].to_string(index=False))

pivot.to_csv("density_sweep_golden_vs_random.csv", index=False)

# -------------------------
# Plot 1: per-dataset curves
# -------------------------
for dataset_name in DATASETS:
    sub = summary[summary["dataset"] == dataset_name].copy()

    plt.figure(figsize=(9, 5))
    for mode in MODES:
        dsub = sub[sub["model"] == mode].sort_values("density")
        if len(dsub) == 0:
            continue
        plt.errorbar(
            dsub["density"],
            dsub["mean"],
            yerr=dsub["std"].fillna(0),
            marker="o",
            capsize=4,
            label=mode
        )

    plt.xscale("log")
    plt.xticks(DENSITIES, [f"{d:.0%}" for d in DENSITIES])
    plt.xlabel("Density")
    plt.ylabel("Final Test Accuracy (%)")
    plt.title(f"Density Sweep on {dataset_name}")
    plt.legend()
    plt.tight_layout()
    plt.savefig(f"density_sweep_{dataset_name.lower()}.png", dpi=200)
    plt.show()

# -------------------------
# Plot 2: golden vs random difference
# -------------------------
plt.figure(figsize=(9, 5))
for dataset_name in DATASETS:
    dsub = pivot[pivot["dataset"] == dataset_name].sort_values("density")
    plt.plot(dsub["density"], dsub["golden_minus_random"], marker="o", label=dataset_name)

plt.axhline(0, linestyle="--")
plt.xscale("log")
plt.xticks(DENSITIES, [f"{d:.0%}" for d in DENSITIES])
plt.xlabel("Density")
plt.ylabel("Golden - Random Sparse (%)")
plt.title("Golden vs Random Sparse Across Density")
plt.legend()
plt.tight_layout()
plt.savefig("golden_minus_random_density_sweep.png", dpi=200)
plt.show()

elapsed = time.time() - start_time
print(f"\nDone in {elapsed/60:.1f} minutes.")
print("Use the CSV files and plots for your paper tables/figures.")

