"""using that cvs file to run rest fashionmnist"""

# =========================
# DENSITY SWEEP (FINAL SAFE VERSION)
# MNIST + FashionMNIST
# golden vs random_sparse
# =========================

import math
import random
import os
import time
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

from tqdm.auto import tqdm
from torch.utils.data import DataLoader

# -------------------------
# FORCE CPU (NO CRASH)
# -------------------------
device = torch.device("cpu")
print("⚠️ Running on CPU (safe mode)")

# -------------------------
# CONFIG
# -------------------------
DATASETS = ["MNIST", "FashionMNIST"]
MODES = ["golden", "random_sparse"]
DENSITIES = [0.01, 0.02, 0.05, 0.10]
SEEDS = [0, 1, 2, 3, 4]
EPOCHS = 5

# -------------------------
# SEED
# -------------------------
def seed_everything(seed):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)

# -------------------------
# DATA
# -------------------------
DATASET_STATS = {
    "MNIST": ((0.1307,), (0.3081,)),
    "FashionMNIST": ((0.2860,), (0.3530,))
}

def make_loaders(name):
    mean, std = DATASET_STATS[name]

    transform = transforms.Compose([
        transforms.ToTensor(),
        transforms.Normalize(mean, std)
    ])

    if name == "MNIST":
        train = torchvision.datasets.MNIST("./data", train=True, download=True, transform=transform)
        test = torchvision.datasets.MNIST("./data", train=False, download=True, transform=transform)
    else:
        train = torchvision.datasets.FashionMNIST("./data", train=True, download=True, transform=transform)
        test = torchvision.datasets.FashionMNIST("./data", train=False, download=True, transform=transform)

    return (
        DataLoader(train, batch_size=128, shuffle=True),
        DataLoader(test, batch_size=256, shuffle=False)
    )

# -------------------------
# MASKS
# -------------------------
def golden_angle():
    phi = (1 + 5 ** 0.5) / 2
    return 2 * np.pi * (1 - 1 / phi)

def spiral_mask(out_f, in_f, density, theta):
    total = out_f * in_f
    k = max(1, int(total * density))

    i = np.arange(k * 4)
    r = np.sqrt(i / k)
    t = i * theta

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(int)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(int)

    coords = list(dict.fromkeys(zip(xi, yi)))[:k]

    mask = torch.zeros(out_f, in_f)
    for a, b in coords:
        mask[a, b] = 1.0

    return mask

def random_mask(out_f, in_f, density, gen):
    total = out_f * in_f
    k = max(1, int(total * density))

    mask = torch.zeros(total)
    idx = torch.randperm(total, generator=gen)[:k]
    mask[idx] = 1.0
    return mask.view(out_f, in_f)

# -------------------------
# MODEL
# -------------------------
class MaskedLinear(nn.Module):
    def __init__(self, in_f, out_f, mask):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(out_f, in_f))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_f))
        self.register_buffer("mask", mask)

    def forward(self, x):
        return F.linear(x, self.weight * self.mask, self.bias)

class SparseMLP(nn.Module):
    def __init__(self, mode, density, seed):
        super().__init__()
        gen = torch.Generator().manual_seed(seed)

        if mode == "golden":
            theta = golden_angle()
            m1 = spiral_mask(256, 784, density, theta)
            m2 = spiral_mask(128, 256, density, theta)
            m3 = spiral_mask(10, 128, density, theta)
        else:
            m1 = random_mask(256, 784, density, gen)
            m2 = random_mask(128, 256, density, gen)
            m3 = random_mask(10, 128, density, gen)

        self.net = nn.Sequential(
            MaskedLinear(784,256,m1), nn.ReLU(),
            MaskedLinear(256,128,m2), nn.ReLU(),
            MaskedLinear(128,10,m3)
        )

    def forward(self,x):
        return self.net(x)

# -------------------------
# TRAIN / EVAL
# -------------------------
def evaluate(model, loader):
    model.eval()
    correct = 0
    total = 0
    with torch.no_grad():
        for x,y in loader:
            x = x.view(x.size(0), -1)
            pred = model(x).argmax(1)
            correct += (pred==y).sum().item()
            total += y.size(0)
    return 100*correct/total

def train_one(model, train_loader, test_loader, name):
    model.to(device)
    opt = optim.Adam(model.parameters(), lr=1e-3)
    loss_fn = nn.CrossEntropyLoss()

    for epoch in range(5):
        model.train()
        for x,y in train_loader:
            x = x.view(x.size(0), -1)
            opt.zero_grad()
            loss = loss_fn(model(x), y)
            loss.backward()
            opt.step()

    return evaluate(model, test_loader)

# -------------------------
# RESUME SUPPORT
# -------------------------
if os.path.exists("density_results.csv"):
    df_existing = pd.read_csv("density_results.csv")
    done = set(zip(df_existing.dataset, df_existing.density, df_existing.seed, df_existing.model))
    results = df_existing.to_dict("records")
    print("Resuming from saved file...")
else:
    done = set()
    results = []

# -------------------------
# MAIN LOOP
# -------------------------
print("\nStarting experiment...")

for dataset in DATASETS:
    train_loader, test_loader = make_loaders(dataset)

    for density in DENSITIES:
        for seed in SEEDS:
            for mode in MODES:

                key = (dataset, density, seed, mode)

                if key in done:
                    print("⏭️ Skipping", key)
                    continue

                print(f"\n🚀 {dataset} | {mode} | d={density:.2%} | seed={seed}")

                seed_everything(seed)
                model = SparseMLP(mode, density, seed)

                acc = train_one(model, train_loader, test_loader, mode)

                print(f"✅ Final Acc: {acc:.2f}%")

                results.append({
                    "dataset": dataset,
                    "density": density,
                    "seed": seed,
                    "model": mode,
                    "acc": acc
                })

                pd.DataFrame(results).to_csv("density_results.csv", index=False)
                print("💾 Saved")

# -------------------------
# SUMMARY
# -------------------------
df = pd.DataFrame(results)

summary = df.groupby(["dataset","density","model"])["acc"].agg(["mean","std"]).reset_index()

print("\n===== FINAL SUMMARY =====")
print(summary)

summary.to_csv("density_summary.csv", index=False)

# -------------------------
# DIFFERENCE (KEY RESULT)
# -------------------------
pivot = summary.pivot_table(index=["dataset","density"], columns="model", values="mean").reset_index()
pivot["golden_minus_random"] = pivot["golden"] - pivot["random_sparse"]

print("\n===== GOLDEN ADVANTAGE =====")
print(pivot)

pivot.to_csv("golden_vs_random.csv", index=False)

# -------------------------
# PLOT
# -------------------------
for dataset in DATASETS:
    sub = summary[summary["dataset"]==dataset]

    plt.figure()
    for mode in MODES:
        d = sub[sub["model"]==mode].sort_values("density")
        plt.plot(d["density"], d["mean"], marker="o", label=mode)

    plt.xscale("log")
    plt.xticks(DENSITIES, [f"{int(d*100)}%" for d in DENSITIES])
    plt.title(dataset)
    plt.xlabel("Density")
    plt.ylabel("Accuracy")
    plt.legend()
    plt.show()

print("\n✅ DONE")

