if "random_sparse" in example_masks and example_masks["random_sparse"] is not None:
    plt.figure(figsize=(10, 4))
    plt.imshow(example_masks["random_sparse"].view(example_masks["random_sparse"].shape[0], -1).numpy(), aspect="auto", cmap="viridis")
    plt.colorbar()
