# ============================================================
# Edge Microbenchmark: CIFAR-10 Tiny CNN
# Golden sparse vs Random sparse
#
# 100 runs total = 50 seeds x 2 models
# One fixed tiny dataset subset
# One fixed initialization per seed
# One fixed short training budget per run
# Checkpoints at 5 / 10 / 20 steps
#
# This is designed to answer:
# "Does the golden-angle idea survive a harsh, edge-like budget?"
# ============================================================

import os
import math
import time
import random
from contextlib import nullcontext

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

from tqdm.auto import tqdm
from torch.utils.data import DataLoader, Subset

# -------------------------
# Device
# -------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)
if device.type == "cuda":
    print("🔥 GPU:", torch.cuda.get_device_name(0))

use_amp = device.type == "cuda"

# -------------------------
# Config
# -------------------------
DATASET_NAME = "CIFAR10"
MODES = ["golden", "random_sparse"]

# Very sparse, edge-style budget
DENSITY = 0.02

# 50 seeds x 2 models = 100 runs total
SEEDS = list(range(50))

# short budget, but enough to show learning direction
MAX_STEPS = 20
CHECKPOINT_STEPS = [5, 10, 20]

LR = 2e-3
WEIGHT_DECAY = 1e-4

BATCH_SIZE_TRAIN = 128
BATCH_SIZE_TEST = 256

TRAIN_SUBSET_SIZE = 3072
TEST_SUBSET_SIZE = 1000

RESULTS_CSV = "edge_microbench_cifar10_results.csv"
SUMMARY_CSV = "edge_microbench_cifar10_summary.csv"

# Fixed subset seed so every run sees the same examples
SUBSET_SEED = 12345

# -------------------------
# Reproducibility
# -------------------------
def seed_everything(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

if use_amp:
    torch.backends.cudnn.benchmark = True

try:
    torch.set_float32_matmul_precision("high")
except Exception:
    pass

# -------------------------
# CIFAR-10 data
# -------------------------
CIFAR10_MEAN = (0.4914, 0.4822, 0.4465)
CIFAR10_STD = (0.2023, 0.1994, 0.2010)

train_transform = transforms.Compose([
    transforms.RandomCrop(32, padding=4),
    transforms.RandomHorizontalFlip(),
    transforms.ToTensor(),
    transforms.Normalize(CIFAR10_MEAN, CIFAR10_STD),
])

test_transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize(CIFAR10_MEAN, CIFAR10_STD),
])

full_train = torchvision.datasets.CIFAR10(
    root="./data", train=True, download=True, transform=train_transform
)
full_test = torchvision.datasets.CIFAR10(
    root="./data", train=False, download=True, transform=test_transform
)

def fixed_subset(dataset, size, seed):
    g = torch.Generator().manual_seed(seed)
    idx = torch.randperm(len(dataset), generator=g)[:size].tolist()
    return Subset(dataset, idx)

train_subset = fixed_subset(full_train, TRAIN_SUBSET_SIZE, SUBSET_SEED)
test_subset = fixed_subset(full_test, TEST_SUBSET_SIZE, SUBSET_SEED + 1)

# shuffle=False keeps the exact same order across golden/random within a seed
train_loader = DataLoader(
    train_subset,
    batch_size=BATCH_SIZE_TRAIN,
    shuffle=False,
    num_workers=0,
    pin_memory=use_amp,
)

test_loader = DataLoader(
    test_subset,
    batch_size=BATCH_SIZE_TEST,
    shuffle=False,
    num_workers=0,
    pin_memory=use_amp,
)

# -------------------------
# Mask helpers
# -------------------------
def golden_angle():
    phi = (1 + 5 ** 0.5) / 2
    return 2 * np.pi * (1 - 1 / phi)

def spiral_mask(out_f: int, in_f: int, density: float, theta_step: float):
    total = out_f * in_f
    k = max(1, int(round(total * density)))

    # oversample to survive collisions
    n = max(k * 4, k + 32)
    i = np.arange(n, dtype=np.float64)

    r = np.sqrt(i / max(1, k))
    t = i * theta_step

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(np.int64)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(np.int64)

    coords = list(dict.fromkeys(zip(xi.tolist(), yi.tolist())))[:k]

    mask = torch.zeros(out_f, in_f, dtype=torch.float32)
    for a, b in coords:
        mask[a, b] = 1.0

    # deterministic fallback fill to guarantee exact active count
    current = int(mask.sum().item())
    if current < k:
        for a in range(out_f):
            for b in range(in_f):
                if current >= k:
                    break
                if mask[a, b].item() == 0:
                    mask[a, b] = 1.0
                    current += 1
            if current >= k:
                break

    return mask

def random_mask(out_f: int, in_f: int, density: float, gen: torch.Generator):
    total = out_f * in_f
    k = max(1, int(round(total * density)))
    mask = torch.zeros(total, dtype=torch.float32)
    idx = torch.randperm(total, generator=gen)[:k]
    mask[idx] = 1.0
    return mask.view(out_f, in_f)

def make_weight_mask(weight_shape, mode: str, density: float, seed: int):
    gen = torch.Generator().manual_seed(seed)
    theta = golden_angle()

    if len(weight_shape) == 2:
        out_f, in_f = weight_shape
        if mode == "golden":
            return spiral_mask(out_f, in_f, density, theta)
        elif mode == "random_sparse":
            return random_mask(out_f, in_f, density, gen)
        else:
            raise ValueError(f"Unknown mode: {mode}")

    if len(weight_shape) == 4:
        out_c, in_c, kh, kw = weight_shape
        flat_in = in_c * kh * kw
        if mode == "golden":
            flat = spiral_mask(out_c, flat_in, density, theta)
        elif mode == "random_sparse":
            flat = random_mask(out_c, flat_in, density, gen)
        else:
            raise ValueError(f"Unknown mode: {mode}")
        return flat.view(out_c, in_c, kh, kw)

    raise ValueError(f"Unsupported weight shape: {weight_shape}")

# -------------------------
# Layers
# -------------------------
class MaskedConv2d(nn.Module):
    def __init__(self, in_ch, out_ch, kernel_size, stride=1, padding=0, bias=True, mask=None):
        super().__init__()
        if isinstance(kernel_size, int):
            kh = kw = kernel_size
        else:
            kh, kw = kernel_size

        self.weight = nn.Parameter(torch.empty(out_ch, in_ch, kh, kw))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_ch)) if bias else None
        self.stride = stride
        self.padding = padding
        self.register_buffer("mask", mask.float())

    def forward(self, x):
        return F.conv2d(x, self.weight * self.mask, self.bias, stride=self.stride, padding=self.padding)

class MaskedLinear(nn.Module):
    def __init__(self, in_f, out_f, bias=True, mask=None):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(out_f, in_f))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_f)) if bias else None
        self.register_buffer("mask", mask.float())

    def forward(self, x):
        return F.linear(x, self.weight * self.mask, self.bias)

# -------------------------
# Tiny edge-style CNN
# -------------------------
class TinyEdgeCNNMasked(nn.Module):
    def __init__(self, mode: str, density: float, seed: int, num_classes: int = 10):
        super().__init__()

        self.conv1 = MaskedConv2d(
            3, 16, kernel_size=3, stride=1, padding=1, bias=True,
            mask=make_weight_mask((16, 3, 3, 3), mode, density, seed + 1)
        )
        self.gn1 = nn.GroupNorm(4, 16)

        self.conv2 = MaskedConv2d(
            16, 32, kernel_size=3, stride=2, padding=1, bias=True,
            mask=make_weight_mask((32, 16, 3, 3), mode, density, seed + 2)
        )
        self.gn2 = nn.GroupNorm(8, 32)

        self.conv3 = MaskedConv2d(
            32, 64, kernel_size=3, stride=2, padding=1, bias=True,
            mask=make_weight_mask((64, 32, 3, 3), mode, density, seed + 3)
        )
        self.gn3 = nn.GroupNorm(8, 64)

        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.fc = MaskedLinear(
            64, num_classes, bias=True,
            mask=make_weight_mask((num_classes, 64), mode, density, seed + 999)
        )

    def forward(self, x):
        x = self.conv1(x)
        x = self.gn1(x)
        x = F.relu(x, inplace=True)

        x = self.conv2(x)
        x = self.gn2(x)
        x = F.relu(x, inplace=True)

        x = self.conv3(x)
        x = self.gn3(x)
        x = F.relu(x, inplace=True)

        x = self.pool(x)
        x = torch.flatten(x, 1)
        x = self.fc(x)
        return x

# -------------------------
# Counting
# -------------------------
def model_report(model):
    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    active_weights = 0
    total_weights = 0

    for m in model.modules():
        if isinstance(m, (MaskedConv2d, MaskedLinear)):
            active_weights += int(m.mask.sum().item())
            total_weights += m.weight.numel()
            if m.bias is not None:
                active_weights += m.bias.numel()
                total_weights += m.bias.numel()
        elif isinstance(m, (nn.Conv2d, nn.Linear)):
            active_weights += m.weight.numel()
            total_weights += m.weight.numel()
            if m.bias is not None:
                active_weights += m.bias.numel()
                total_weights += m.bias.numel()

    return {
        "trainable_params": trainable_params,
        "active_params_in_forward": active_weights,
        "total_possible_params": total_weights,
    }

# -------------------------
# AMP helpers
# -------------------------
def amp_context():
    if use_amp:
        return torch.amp.autocast(device_type="cuda", enabled=True)
    return nullcontext()

criterion = nn.CrossEntropyLoss()

@torch.no_grad()
def evaluate(model, loader):
    model.eval()
    total_loss = 0.0
    correct = 0
    total = 0

    for x, y in loader:
        x = x.to(device, non_blocking=True)
        y = y.to(device, non_blocking=True)

        with amp_context():
            logits = model(x)
            loss = criterion(logits, y)

        total_loss += loss.item() * y.size(0)
        correct += (logits.argmax(dim=1) == y).sum().item()
        total += y.size(0)

    return total_loss / total, 100.0 * correct / total

# -------------------------
# Resume support
# -------------------------
results_cols = [
    "dataset", "density", "seed", "model", "step",
    "train_loss", "train_acc", "test_loss", "test_acc", "elapsed_sec"
]

def make_key(dataset, density, seed, model):
    return (str(dataset), round(float(density), 6), int(seed), str(model))

def save_results(rows):
    if len(rows) == 0:
        return
    pd.DataFrame(rows).to_csv(RESULTS_CSV, index=False)

results_rows = []
completed = set()

if os.path.exists(RESULTS_CSV):
    existing = pd.read_csv(RESULTS_CSV)
    existing = existing[[c for c in existing.columns if c in results_cols]].copy()

    if len(existing) > 0:
        cleaned_groups = []
        for key, g in existing.groupby(["dataset", "density", "seed", "model"]):
            if int(g["step"].max()) >= MAX_STEPS:
                cleaned_groups.append(g)
                completed.add(make_key(*key))

        if cleaned_groups:
            existing = pd.concat(cleaned_groups, ignore_index=True)
        else:
            existing = existing.iloc[0:0].copy()

        results_rows = existing.to_dict("records")
        print(f"Resuming from {RESULTS_CSV}. Completed runs: {len(completed)}")
else:
    print("Starting fresh.")

# -------------------------
# Training
# -------------------------
def train_budget(model, train_loader, test_loader, name: str, dataset_name: str, density: float, seed: int, mode: str):
    model.to(device)
    optimizer = optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)
    scaler = torch.amp.GradScaler("cuda", enabled=use_amp)

    rows = []
    start = time.time()
    step = 0

    model.train()
    pbar = tqdm(train_loader, desc=f"{name}", leave=False)

    for x, y in pbar:
        x = x.to(device, non_blocking=True)
        y = y.to(device, non_blocking=True)

        optimizer.zero_grad(set_to_none=True)

        with amp_context():
            logits = model(x)
            loss = criterion(logits, y)

        if use_amp:
            scaler.scale(loss).backward()
            scaler.step(optimizer)
            scaler.update()
        else:
            loss.backward()
            optimizer.step()

        step += 1
        running_pred = logits.argmax(dim=1)
        batch_acc = (running_pred == y).float().mean().item() * 100.0

        pbar.set_postfix(step=step, loss=f"{loss.item():.4f}", batch_acc=f"{batch_acc:.2f}%")

        if step in CHECKPOINT_STEPS:
            test_loss, test_acc = evaluate(model, test_loader)
            elapsed_sec = time.time() - start

            row = {
                "dataset": dataset_name,
                "density": density,
                "seed": seed,
                "model": mode,
                "step": step,
                "train_loss": float(loss.item()),
                "train_acc": float(batch_acc),
                "test_loss": float(test_loss),
                "test_acc": float(test_acc),
                "elapsed_sec": float(elapsed_sec),
            }
            rows.append(row)
            results_rows.append(row)
            save_results(results_rows)

            print(
                f"✅ {name} | step {step:02d} | "
                f"test={test_acc:.2f}% | elapsed={elapsed_sec:.1f}s"
            )

        if step >= MAX_STEPS:
            break

    return pd.DataFrame(rows)

# -------------------------
# Run
# -------------------------
start_time = time.time()
print("\nStarting edge microbenchmark...")

example_masks = {}

for seed in SEEDS:
    key_g = make_key(DATASET_NAME, DENSITY, seed, "golden")
    key_r = make_key(DATASET_NAME, DENSITY, seed, "random_sparse")

    for mode in MODES:
        key = make_key(DATASET_NAME, DENSITY, seed, mode)
        if key in completed:
            print(f"⏭️ Skipping completed run: {mode} | seed={seed}")
            continue

        print(f"\n🚀 {DATASET_NAME} | {mode} | density={DENSITY:.2%} | seed={seed}")

        # same seed gives same init; mode changes only the mask
        seed_everything(seed)

        model = TinyEdgeCNNMasked(mode=mode, density=DENSITY, seed=seed)

        report = model_report(model)
        print(f"{mode} counts: {report}")

        hist = train_budget(
            model=model,
            train_loader=train_loader,
            test_loader=test_loader,
            name=f"{mode} seed={seed}",
            dataset_name=DATASET_NAME,
            density=DENSITY,
            seed=seed,
            mode=mode,
        )

        if mode == "golden" and seed == SEEDS[0] and hasattr(model, "conv1"):
            example_masks["golden"] = model.conv1.mask.detach().cpu().clone()
        if mode == "random_sparse" and seed == SEEDS[0] and hasattr(model, "conv1"):
            example_masks["random_sparse"] = model.conv1.mask.detach().cpu().clone()

        print(f"💾 Saved progress to {RESULTS_CSV}")

# -------------------------
# Summary
# -------------------------
df = pd.DataFrame(results_rows)
df.to_csv(RESULTS_CSV, index=False)

finals = df[df["step"] == MAX_STEPS].copy()

summary = (
    finals.groupby(["dataset", "density", "model"])
    .agg(
        mean_test_acc=("test_acc", "mean"),
        std_test_acc=("test_acc", "std"),
        mean_train_acc=("train_acc", "mean"),
        std_train_acc=("train_acc", "std"),
        mean_elapsed_sec=("elapsed_sec", "mean"),
        std_elapsed_sec=("elapsed_sec", "std"),
    )
    .reset_index()
    .sort_values(["dataset", "density", "model"])
)

summary.to_csv(SUMMARY_CSV, index=False)

print("\n===== FINAL SUMMARY AT STEP 20 =====")
print(summary.to_string(index=False))

checkpoint_summary = (
    df[df["step"].isin(CHECKPOINT_STEPS)]
    .groupby(["step", "model"])
    .agg(
        mean_test_acc=("test_acc", "mean"),
        std_test_acc=("test_acc", "std"),
        mean_elapsed_sec=("elapsed_sec", "mean"),
    )
    .reset_index()
    .sort_values(["step", "model"])
)

print("\n===== CHECKPOINT SUMMARY =====")
print(checkpoint_summary.to_string(index=False))

# Paired golden vs random difference at each checkpoint, seed matched
pair = (
    df[df["step"].isin(CHECKPOINT_STEPS)]
    .pivot_table(index=["seed", "step"], columns="model", values="test_acc")
    .reset_index()
)

if "golden" in pair.columns and "random_sparse" in pair.columns:
    pair["golden_minus_random"] = pair["golden"] - pair["random_sparse"]

    print("\n===== PAIRED GOLDEN - RANDOM_SPARSE =====")
    print(
        pair.groupby("step")["golden_minus_random"]
        .agg(["mean", "std"])
        .reset_index()
        .to_string(index=False)
    )

# -------------------------
# Plots
# -------------------------
curve = (
    df.groupby(["step", "model"])
    .agg(
        mean_test_acc=("test_acc", "mean"),
        std_test_acc=("test_acc", "std"),
    )
    .reset_index()
)

plt.figure(figsize=(9, 5))
for mode in MODES:
    sub = curve[curve["model"] == mode].sort_values("step")
    if len(sub) == 0:
        continue
    plt.plot(sub["step"], sub["mean_test_acc"], marker="o", label=mode)
    std = sub["std_test_acc"].fillna(0)
    plt.fill_between(
        sub["step"],
        sub["mean_test_acc"] - std,
        sub["mean_test_acc"] + std,
        alpha=0.15
    )

plt.xlabel("Training step")
plt.ylabel("Test Accuracy (%)")
plt.title("CIFAR-10 Edge Microbenchmark: Golden vs Random Sparse")
plt.legend()
plt.tight_layout()
plt.savefig("edge_microbenchmark_curve.png", dpi=200)
plt.show()

plt.figure(figsize=(8, 5))
for mode in MODES:
    vals = finals[finals["model"] == mode]["test_acc"]
    if len(vals) > 0:
        plt.scatter([mode] * len(vals), vals)

plt.ylabel("Final Test Accuracy (%)")
plt.title(f"CIFAR-10 Final Accuracy at Step {MAX_STEPS}")
plt.tight_layout()
plt.savefig("edge_microbenchmark_final_scatter.png", dpi=200)
plt.show()

if "golden" in example_masks and example_masks["golden"] is not None:
    plt.figure(figsize=(10, 4))
    plt.imshow(
        example_masks["golden"].view(example_masks["golden"].shape[0], -1).numpy(),
        aspect="auto",
        cmap="viridis",
    )
    plt.colorbar()
    plt.title("Golden Sparse Mask - Stem Conv (flattened)")
    plt.tight_layout()
    plt.savefig("edge_microbenchmark_golden_mask.png", dpi=200)
    plt.show()

if "random_sparse" in example_masks and example_masks["random_sparse"] is not None:
    plt.figure(figsize=(10, 4))
    plt.imshow(
        example_masks["random_sparse"].view(example_masks["random_sparse"].shape[0], -1).numpy(),
        aspect="auto",
        cmap="viridis",
    )
    plt.colorbar()
    plt.title("Random Sparse Mask - Stem Conv (flattened)")
    plt.tight_layout()
    plt.savefig("edge_microbenchmark_random_mask.png", dpi=200)
    plt.show()

elapsed = time.time() - start_time
print(f"\nDone in {elapsed/60:.1f} minutes.")
print(f"Results saved to {RESULTS_CSV}")
print(f"Summary saved to {SUMMARY_CSV}")

"""CIFAR-10 Edge Microbenchmark + Dead-Neuron Diagnostic
# Golden sparse vs Random sparse
"""

# ============================================================
# CIFAR-10 Edge Microbenchmark + Dead-Neuron Diagnostic
# Golden sparse vs Random sparse
#
# Settings:
#   - densities: 1%, 2%
#   - modes: golden, random_sparse
#   - paired seeds
#   - fixed tiny CIFAR-10 subset
#   - 20 training steps total
#   - checkpoints at steps 5 / 10 / 20
#
# Outputs:
#   - CSV logs
#   - summary table
#   - golden-vs-random gap table
#   - dead-neuron diagnostic
#   - plots
# ============================================================

import os
import math
import time
import random
from contextlib import nullcontext

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

from tqdm.auto import tqdm
from torch.utils.data import DataLoader, Subset

# -------------------------
# Device
# -------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)
if device.type == "cuda":
    print("🔥 GPU:", torch.cuda.get_device_name(0))

USE_AMP = device.type == "cuda"
if USE_AMP:
    torch.backends.cudnn.benchmark = True

try:
    torch.set_float32_matmul_precision("high")
except Exception:
    pass

# -------------------------
# Config
# -------------------------
DATASET_NAME = "CIFAR10"
MODES = ["golden", "random_sparse"]
DENSITIES = [0.01, 0.02]
SEEDS = list(range(20))  # 20 paired seeds = 40 runs total

MAX_STEPS = 20
CHECKPOINT_STEPS = [5, 10, 20]

LR = 2e-3
WEIGHT_DECAY = 1e-4

BATCH_SIZE_TRAIN = 128
BATCH_SIZE_TEST = 256

TRAIN_SUBSET_SIZE = 5000
TEST_SUBSET_SIZE = 1000

SUBSET_SEED = 12345

RESULTS_CSV = "cifar10_edge_deadneuron_results.csv"
SUMMARY_CSV = "cifar10_edge_deadneuron_summary.csv"

# -------------------------
# Reproducibility
# -------------------------
def seed_everything(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -------------------------
# CIFAR-10 data
# -------------------------
CIFAR10_MEAN = (0.4914, 0.4822, 0.4465)
CIFAR10_STD = (0.2023, 0.1994, 0.2010)

train_transform = transforms.Compose([
    transforms.RandomCrop(32, padding=4),
    transforms.RandomHorizontalFlip(),
    transforms.ToTensor(),
    transforms.Normalize(CIFAR10_MEAN, CIFAR10_STD),
])

test_transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize(CIFAR10_MEAN, CIFAR10_STD),
])

full_train = torchvision.datasets.CIFAR10(
    root="./data", train=True, download=True, transform=train_transform
)
full_test = torchvision.datasets.CIFAR10(
    root="./data", train=False, download=True, transform=test_transform
)

def fixed_subset(dataset, size, seed):
    g = torch.Generator().manual_seed(seed)
    idx = torch.randperm(len(dataset), generator=g)[:size].tolist()
    return Subset(dataset, idx)

train_subset = fixed_subset(full_train, TRAIN_SUBSET_SIZE, SUBSET_SEED)
test_subset = fixed_subset(full_test, TEST_SUBSET_SIZE, SUBSET_SEED + 1)

train_loader = DataLoader(
    train_subset,
    batch_size=BATCH_SIZE_TRAIN,
    shuffle=False,   # same order for every paired run
    num_workers=0,
    pin_memory=USE_AMP,
)

test_loader = DataLoader(
    test_subset,
    batch_size=BATCH_SIZE_TEST,
    shuffle=False,
    num_workers=0,
    pin_memory=USE_AMP,
)

# -------------------------
# Mask helpers
# -------------------------
def golden_angle():
    phi = (1 + 5 ** 0.5) / 2
    return 2 * np.pi * (1 - 1 / phi)

def spiral_mask(out_f: int, in_f: int, density: float, theta_step: float):
    """
    Deterministic exact-density mask for a 2D weight matrix.
    """
    total = out_f * in_f
    k = max(1, int(round(total * density)))

    # Oversample to reduce collision loss.
    n = max(k * 4, k + 32)
    i = np.arange(n, dtype=np.float64)

    r = np.sqrt(i / max(1, k))
    t = i * theta_step

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(np.int64)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(np.int64)

    coords = list(dict.fromkeys(zip(xi.tolist(), yi.tolist())))[:k]

    mask = torch.zeros(out_f, in_f, dtype=torch.float32)
    for a, b in coords:
        mask[a, b] = 1.0

    # Fallback fill to guarantee exact active count
    current = int(mask.sum().item())
    if current < k:
        for a in range(out_f):
            for b in range(in_f):
                if current >= k:
                    break
                if mask[a, b].item() == 0:
                    mask[a, b] = 1.0
                    current += 1
            if current >= k:
                break

    return mask

def random_mask(out_f: int, in_f: int, density: float, gen: torch.Generator):
    total = out_f * in_f
    k = max(1, int(round(total * density)))
    mask = torch.zeros(total, dtype=torch.float32)
    idx = torch.randperm(total, generator=gen)[:k]
    mask[idx] = 1.0
    return mask.view(out_f, in_f)

def make_weight_mask(weight_shape, mode: str, density: float, seed: int):
    gen = torch.Generator().manual_seed(seed)
    theta = golden_angle()

    if len(weight_shape) == 2:
        out_f, in_f = weight_shape
        if mode == "golden":
            return spiral_mask(out_f, in_f, density, theta)
        elif mode == "random_sparse":
            return random_mask(out_f, in_f, density, gen)
        else:
            raise ValueError(f"Unknown mode: {mode}")

    if len(weight_shape) == 4:
        out_c, in_c, kh, kw = weight_shape
        flat_in = in_c * kh * kw

        if mode == "golden":
            flat = spiral_mask(out_c, flat_in, density, theta)
        elif mode == "random_sparse":
            flat = random_mask(out_c, flat_in, density, gen)
        else:
            raise ValueError(f"Unknown mode: {mode}")

        return flat.view(out_c, in_c, kh, kw)

    raise ValueError(f"Unsupported weight shape: {weight_shape}")

# -------------------------
# Masked layers
# -------------------------
class MaskedConv2d(nn.Module):
    def __init__(self, in_ch, out_ch, kernel_size, stride=1, padding=0, bias=True, mask=None):
        super().__init__()
        if isinstance(kernel_size, int):
            kh = kw = kernel_size
        else:
            kh, kw = kernel_size

        self.weight = nn.Parameter(torch.empty(out_ch, in_ch, kh, kw))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_ch)) if bias else None
        self.stride = stride
        self.padding = padding
        self.register_buffer("mask", mask.float())

    def forward(self, x):
        return F.conv2d(
            x,
            self.weight * self.mask,
            self.bias,
            stride=self.stride,
            padding=self.padding,
        )

class MaskedLinear(nn.Module):
    def __init__(self, in_f, out_f, bias=True, mask=None):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(out_f, in_f))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_f)) if bias else None
        self.register_buffer("mask", mask.float())

    def forward(self, x):
        return F.linear(x, self.weight * self.mask, self.bias)

# -------------------------
# Tiny edge CNN
# -------------------------
class TinyEdgeCNNMasked(nn.Module):
    def __init__(self, mode: str, density: float, seed: int, num_classes: int = 10):
        super().__init__()

        self.conv1 = MaskedConv2d(
            3, 16, kernel_size=3, stride=1, padding=1, bias=True,
            mask=make_weight_mask((16, 3, 3, 3), mode, density, seed + 1)
        )
        self.gn1 = nn.GroupNorm(4, 16)

        self.conv2 = MaskedConv2d(
            16, 32, kernel_size=3, stride=2, padding=1, bias=True,
            mask=make_weight_mask((32, 16, 3, 3), mode, density, seed + 2)
        )
        self.gn2 = nn.GroupNorm(8, 32)

        self.conv3 = MaskedConv2d(
            32, 64, kernel_size=3, stride=2, padding=1, bias=True,
            mask=make_weight_mask((64, 32, 3, 3), mode, density, seed + 3)
        )
        self.gn3 = nn.GroupNorm(8, 64)

        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.fc = MaskedLinear(
            64, num_classes, bias=True,
            mask=make_weight_mask((num_classes, 64), mode, density, seed + 999)
        )

    def forward(self, x):
        x = F.relu(self.gn1(self.conv1(x)), inplace=True)
        x = F.relu(self.gn2(self.conv2(x)), inplace=True)
        x = F.relu(self.gn3(self.conv3(x)), inplace=True)
        x = self.pool(x)
        x = torch.flatten(x, 1)
        x = self.fc(x)
        return x

# -------------------------
# Diagnostics
# -------------------------
def connectivity_diagnostic(model):
    """
    Counts dead output neurons/channels for each masked layer.
    A dead output neuron = zero active incoming connections in that layer.
    """
    details = {}
    total_dead = 0
    total_neurons = 0
    total_active = 0
    total_possible = 0

    for name, module in model.named_modules():
        if hasattr(module, "mask"):
            mask = module.mask.detach().cpu()
            flat = mask.view(mask.size(0), -1)
            active_per_out = flat.sum(dim=1)
            dead = int((active_per_out == 0).sum().item())
            out_units = int(mask.size(0))
            active = int(mask.sum().item())
            possible = int(mask.numel())

            details[name] = {
                "dead": dead,
                "total_out": out_units,
                "dead_pct": 100.0 * dead / max(1, out_units),
                "active_weights": active,
                "possible_weights": possible,
            }

            total_dead += dead
            total_neurons += out_units
            total_active += active
            total_possible += possible

    overall_dead_pct = 100.0 * total_dead / max(1, total_neurons)
    overall_sparsity_pct = 100.0 * (1.0 - (total_active / max(1, total_possible)))

    return {
        "overall_dead_pct": overall_dead_pct,
        "overall_sparsity_pct": overall_sparsity_pct,
        "details": details,
    }

def model_report(model):
    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    active_weights = 0
    total_weights = 0

    for m in model.modules():
        if isinstance(m, (MaskedConv2d, MaskedLinear)):
            active_weights += int(m.mask.sum().item())
            total_weights += m.weight.numel()
            if m.bias is not None:
                active_weights += m.bias.numel()
                total_weights += m.bias.numel()

    return {
        "trainable_params": trainable_params,
        "active_params_in_forward": active_weights,
        "total_possible_params": total_weights,
    }

# -------------------------
# AMP helpers
# -------------------------
def amp_context():
    if USE_AMP:
        return torch.amp.autocast(device_type="cuda", enabled=True)
    return nullcontext()

criterion = nn.CrossEntropyLoss()

@torch.no_grad()
def evaluate(model, loader):
    model.eval()
    total_loss = 0.0
    correct = 0
    total = 0

    for x, y in loader:
        x = x.to(device, non_blocking=True)
        y = y.to(device, non_blocking=True)

        with amp_context():
            logits = model(x)
            loss = criterion(logits, y)

        total_loss += loss.item() * y.size(0)
        correct += (logits.argmax(dim=1) == y).sum().item()
        total += y.size(0)

    return total_loss / total, 100.0 * correct / total

# -------------------------
# Training
# -------------------------
def train_budget(
    model,
    train_loader,
    test_loader,
    name: str,
    dataset_name: str,
    density: float,
    seed: int,
    mode: str,
    dead_diag: dict,
):
    model.to(device)
    optimizer = optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)

    scaler = torch.amp.GradScaler("cuda", enabled=USE_AMP) if USE_AMP else None

    rows = []
    start = time.time()
    step = 0

    model.train()
    pbar = tqdm(train_loader, desc=f"{name}", leave=False)

    for x, y in pbar:
        x = x.to(device, non_blocking=True)
        y = y.to(device, non_blocking=True)

        optimizer.zero_grad(set_to_none=True)

        with amp_context():
            logits = model(x)
            loss = criterion(logits, y)

        if USE_AMP:
            scaler.scale(loss).backward()
            scaler.step(optimizer)
            scaler.update()
        else:
            loss.backward()
            optimizer.step()

        step += 1
        batch_acc = (logits.argmax(dim=1) == y).float().mean().item() * 100.0

        pbar.set_postfix(step=step, loss=f"{loss.item():.4f}", batch_acc=f"{batch_acc:.2f}%")

        if step in CHECKPOINT_STEPS:
            test_loss, test_acc = evaluate(model, test_loader)
            elapsed_sec = time.time() - start

            row = {
                "dataset": dataset_name,
                "density": density,
                "seed": seed,
                "model": mode,
                "step": step,
                "train_loss": float(loss.item()),
                "train_acc": float(batch_acc),
                "test_loss": float(test_loss),
                "test_acc": float(test_acc),
                "elapsed_sec": float(elapsed_sec),
                "dead_overall_pct": float(dead_diag["overall_dead_pct"]),
                "overall_sparsity_pct": float(dead_diag["overall_sparsity_pct"]),
            }
            rows.append(row)
            print(
                f"✅ {name} | step {step:02d} | "
                f"test={test_acc:.2f}% | dead={dead_diag['overall_dead_pct']:.1f}% | "
                f"elapsed={elapsed_sec:.1f}s"
            )

        if step >= MAX_STEPS:
            break

    return pd.DataFrame(rows)

# -------------------------
# Resume support
# -------------------------
results_cols = [
    "dataset", "density", "seed", "model", "step",
    "train_loss", "train_acc", "test_loss", "test_acc",
    "elapsed_sec", "dead_overall_pct", "overall_sparsity_pct"
]

def make_key(dataset, density, seed, model):
    return (str(dataset), round(float(density), 6), int(seed), str(model))

results_rows = []
completed = set()

if os.path.exists(RESULTS_CSV):
    existing = pd.read_csv(RESULTS_CSV)
    existing = existing[[c for c in existing.columns if c in results_cols]].copy()

    if len(existing) > 0:
        finished = []
        for key, g in existing.groupby(["dataset", "density", "seed", "model"]):
            if int(g["step"].max()) >= MAX_STEPS:
                finished.append(g)
                completed.add(make_key(*key))

        if finished:
            existing = pd.concat(finished, ignore_index=True)
        else:
            existing = existing.iloc[0:0].copy()

        results_rows = existing.to_dict("records")
        print(f"Resuming from {RESULTS_CSV}. Completed runs: {len(completed)}")
else:
    print("Starting fresh.")

# -------------------------
# Run
# -------------------------
start_time = time.time()
print("\nStarting CIFAR-10 edge microbenchmark...")

example_masks = {}

for density in DENSITIES:
    for seed in SEEDS:
        for mode in MODES:
            key = make_key(DATASET_NAME, density, seed, mode)
            if key in completed:
                print(f"⏭️ Skipping completed run: {mode} | density={density:.2%} | seed={seed}")
                continue

            print(f"\n🚀 {DATASET_NAME} | {mode} | density={density:.2%} | seed={seed}")

            seed_everything(seed)

            model = TinyEdgeCNNMasked(mode=mode, density=density, seed=seed)
            report = model_report(model)
            diag = connectivity_diagnostic(model)

            print(f"{mode} counts: {report}")
            print(f"{mode} dead-neuron diagnostic: {diag['details']}")
            print(f"{mode} overall dead neurons: {diag['overall_dead_pct']:.2f}%")
            print(f"{mode} overall sparsity: {diag['overall_sparsity_pct']:.2f}%")

            hist = train_budget(
                model=model,
                train_loader=train_loader,
                test_loader=test_loader,
                name=f"{mode} d={density:.0%} seed={seed}",
                dataset_name=DATASET_NAME,
                density=density,
                seed=seed,
                mode=mode,
                dead_diag=diag,
            )

            for _, row in hist.iterrows():
                results_rows.append(row.to_dict())

            pd.DataFrame(results_rows).to_csv(RESULTS_CSV, index=False)

            if seed == SEEDS[0] and density == DENSITIES[0]:
                if hasattr(model, "conv1") and hasattr(model.conv1, "mask"):
                    example_masks[f"{mode}_{density}"] = model.conv1.mask.detach().cpu().clone()

            print(f"💾 Saved progress to {RESULTS_CSV}")

# -------------------------
# Summary
# -------------------------
df = pd.DataFrame(results_rows)
df.to_csv(RESULTS_CSV, index=False)

finals = df[df["step"] == MAX_STEPS].copy()

summary = (
    finals.groupby(["dataset", "density", "model"])
    .agg(
        mean_test_acc=("test_acc", "mean"),
        std_test_acc=("test_acc", "std"),
        mean_train_acc=("train_acc", "mean"),
        std_train_acc=("train_acc", "std"),
        mean_dead_pct=("dead_overall_pct", "mean"),
        mean_sparsity_pct=("overall_sparsity_pct", "mean"),
        mean_elapsed_sec=("elapsed_sec", "mean"),
    )
    .reset_index()
    .sort_values(["dataset", "density", "model"])
)

summary.to_csv(SUMMARY_CSV, index=False)

print("\n===== FINAL SUMMARY AT STEP 20 =====")
print(summary.to_string(index=False))

# Paired golden vs random differences
pair = (
    finals.pivot_table(
        index=["density", "seed"],
        columns="model",
        values="test_acc"
    )
    .reset_index()
)

if "golden" in pair.columns and "random_sparse" in pair.columns:
    pair["golden_minus_random"] = pair["golden"] - pair["random_sparse"]

    print("\n===== PAIRED GOLDEN - RANDOM_SPARSE =====")
    print(
        pair.groupby("density")["golden_minus_random"]
        .agg(["mean", "std"])
        .reset_index()
        .to_string(index=False)
    )

dead_summary = (
    finals.groupby(["density", "model"])
    .agg(
        mean_dead_pct=("dead_overall_pct", "mean"),
        std_dead_pct=("dead_overall_pct", "std"),
    )
    .reset_index()
    .sort_values(["density", "model"])
)

print("\n===== DEAD-NEURON SUMMARY =====")
print(dead_summary.to_string(index=False))

# -------------------------
# Plots
# -------------------------
curve = (
    df.groupby(["step", "density", "model"])
    .agg(
        mean_test_acc=("test_acc", "mean"),
        std_test_acc=("test_acc", "std"),
        mean_dead_pct=("dead_overall_pct", "mean"),
    )
    .reset_index()
)

for density in DENSITIES:
    plt.figure(figsize=(9, 5))
    sub_d = curve[curve["density"] == density]
    for mode in MODES:
        sub = sub_d[sub_d["model"] == mode].sort_values("step")
        if len(sub) == 0:
            continue
        plt.plot(sub["step"], sub["mean_test_acc"], marker="o", label=mode)
        std = sub["std_test_acc"].fillna(0)
        plt.fill_between(
            sub["step"],
            sub["mean_test_acc"] - std,
            sub["mean_test_acc"] + std,
            alpha=0.15
        )

    plt.xlabel("Training step")
    plt.ylabel("Test Accuracy (%)")
    plt.title(f"CIFAR-10 Edge Microbenchmark @ {density:.0%} density")
    plt.legend()
    plt.tight_layout()
    plt.savefig(f"cifar10_edge_curve_{int(density*100)}pct.png", dpi=200)
    plt.show()

plt.figure(figsize=(8, 5))
for density in DENSITIES:
    sub = finals[finals["density"] == density]
    for mode in MODES:
        vals = sub[sub["model"] == mode]["test_acc"]
        if len(vals) > 0:
            plt.scatter([f"{mode}\n{int(density*100)}%"] * len(vals), vals)

plt.ylabel("Final Test Accuracy (%)")
plt.title("Final Accuracy by Model and Density")
plt.xticks(rotation=20)
plt.tight_layout()
plt.savefig("cifar10_edge_final_scatter.png", dpi=200)
plt.show()

plt.figure(figsize=(8, 5))
for density in DENSITIES:
    sub = pair[pair["density"] == density].copy()
    if len(sub) == 0 or "golden_minus_random" not in sub.columns:
        continue
    plt.scatter([density] * len(sub), sub["golden_minus_random"], label=f"{int(density*100)}%")

plt.axhline(0, linestyle="--")
plt.xlabel("Density")
plt.ylabel("Golden - Random Sparse (%)")
plt.title("Paired Golden Advantage Across Densities")
plt.tight_layout()
plt.savefig("cifar10_edge_golden_minus_random.png", dpi=200)
plt.show()

plt.figure(figsize=(8, 5))
for density in DENSITIES:
    sub = finals[finals["density"] == density]
    for mode in MODES:
        vals = sub[sub["model"] == mode]["dead_overall_pct"]
        if len(vals) > 0:
            plt.scatter([f"{mode}\n{int(density*100)}%"] * len(vals), vals)

plt.ylabel("Dead Neuron Percentage (%)")
plt.title("Dead-Neuron Diagnostic by Model and Density")
plt.xticks(rotation=20)
plt.tight_layout()
plt.savefig("cifar10_edge_dead_neurons.png", dpi=200)
plt.show()

# Mask visualizations
for key, mask in example_masks.items():
    plt.figure(figsize=(10, 4))
    plt.imshow(mask.view(mask.shape[0], -1).numpy(), aspect="auto", cmap="viridis")
    plt.colorbar()
    plt.title(f"First Conv Mask: {key}")
    plt.tight_layout()
    plt.savefig(f"cifar10_edge_mask_{key.replace('.', '_').replace('%','pct')}.png", dpi=200)
    plt.show()

elapsed = time.time() - start_time
print(f"\nDone in {elapsed/60:.1f} minutes.")
print(f"Results saved to {RESULTS_CSV}")
print(f"Summary saved to {SUMMARY_CSV}")

"""# CIFAR-10 Edge Microbenchmark
# Golden sparse vs Random sparse vs Dense
# Densities: 1%, 2%, 5%
# Seeds: 5
"""

# ============================================================
# CIFAR-10 Edge Microbenchmark
# Golden sparse vs Random sparse vs Dense
#
# Densities: 1%, 2%, 5%
# Seeds: 5
# Budget: 20 training steps
# Checkpoints: 5 / 10 / 20 steps
#
# Outputs:
# - CSV logs
# - summary tables
# - separate figures per density
# - dead-neuron diagnostics
# ============================================================

import os
import math
import time
import random
from contextlib import nullcontext

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

from tqdm.auto import tqdm
from torch.utils.data import DataLoader, Subset

# -------------------------
# Device
# -------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)
if device.type == "cuda":
    print("🔥 GPU:", torch.cuda.get_device_name(0))

USE_AMP = device.type == "cuda"
if USE_AMP:
    torch.backends.cudnn.benchmark = False
    torch.backends.cudnn.deterministic = True

try:
    torch.set_float32_matmul_precision("high")
except Exception:
    pass

# -------------------------
# Config
# -------------------------
DATASET_NAME = "CIFAR10"
MODES = ["golden", "random_sparse", "dense"]
DENSITIES = [0.01, 0.02, 0.05]
SEEDS = [0, 1, 2, 3, 4]

MAX_STEPS = 20
CHECKPOINT_STEPS = [5, 10, 20]

LR = 2e-3
WEIGHT_DECAY = 1e-4

BATCH_SIZE_TRAIN = 128
BATCH_SIZE_TEST = 256

TRAIN_SUBSET_SIZE = 3072
TEST_SUBSET_SIZE = 1000
SUBSET_SEED = 12345

RESULTS_CSV = "cifar10_edge_3density_results.csv"
SUMMARY_CSV = "cifar10_edge_3density_summary.csv"
DEAD_CSV = "cifar10_edge_3density_deadneurons.csv"

# -------------------------
# Reproducibility
# -------------------------
def seed_everything(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -------------------------
# Data
# -------------------------
CIFAR10_MEAN = (0.4914, 0.4822, 0.4465)
CIFAR10_STD = (0.2023, 0.1994, 0.2010)

train_transform = transforms.Compose([
    transforms.RandomCrop(32, padding=4),
    transforms.RandomHorizontalFlip(),
    transforms.ToTensor(),
    transforms.Normalize(CIFAR10_MEAN, CIFAR10_STD),
])

test_transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize(CIFAR10_MEAN, CIFAR10_STD),
])

full_train = torchvision.datasets.CIFAR10(
    root="./data", train=True, download=True, transform=train_transform
)
full_test = torchvision.datasets.CIFAR10(
    root="./data", train=False, download=True, transform=test_transform
)

def fixed_subset(dataset, size, seed):
    g = torch.Generator().manual_seed(seed)
    idx = torch.randperm(len(dataset), generator=g)[:size].tolist()
    return Subset(dataset, idx)

train_subset = fixed_subset(full_train, TRAIN_SUBSET_SIZE, SUBSET_SEED)
test_subset = fixed_subset(full_test, TEST_SUBSET_SIZE, SUBSET_SEED + 1)

train_loader = DataLoader(
    train_subset,
    batch_size=BATCH_SIZE_TRAIN,
    shuffle=False,
    num_workers=0,
    pin_memory=USE_AMP,
)
test_loader = DataLoader(
    test_subset,
    batch_size=BATCH_SIZE_TEST,
    shuffle=False,
    num_workers=0,
    pin_memory=USE_AMP,
)

# -------------------------
# Mask helpers
# -------------------------
def golden_angle():
    phi = (1 + 5 ** 0.5) / 2
    return 2 * np.pi * (1 - 1 / phi)

def spiral_mask(out_f: int, in_f: int, density: float, theta_step: float):
    total = out_f * in_f
    k = max(1, int(round(total * density)))

    # oversample so collisions do not ruin exact density
    n = max(k * 4, k + 32)
    i = np.arange(n, dtype=np.float64)

    r = np.sqrt(i / max(1, k))
    t = i * theta_step

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(np.int64)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(np.int64)

    coords = list(dict.fromkeys(zip(xi.tolist(), yi.tolist())))[:k]

    mask = torch.zeros(out_f, in_f, dtype=torch.float32)
    for a, b in coords:
        mask[a, b] = 1.0

    # deterministic fallback fill to guarantee exact k active entries
    current = int(mask.sum().item())
    if current < k:
        for a in range(out_f):
            for b in range(in_f):
                if current >= k:
                    break
                if mask[a, b].item() == 0:
                    mask[a, b] = 1.0
                    current += 1
            if current >= k:
                break

    return mask

def random_mask(out_f: int, in_f: int, density: float, gen: torch.Generator):
    total = out_f * in_f
    k = max(1, int(round(total * density)))
    mask = torch.zeros(total, dtype=torch.float32)
    idx = torch.randperm(total, generator=gen)[:k]
    mask[idx] = 1.0
    return mask.view(out_f, in_f)

def make_weight_mask(weight_shape, mode: str, density: float, seed: int):
    gen = torch.Generator().manual_seed(seed)
    theta = golden_angle()

    if len(weight_shape) == 2:
        out_f, in_f = weight_shape
        if mode == "golden":
            return spiral_mask(out_f, in_f, density, theta)
        if mode == "random_sparse":
            return random_mask(out_f, in_f, density, gen)
        raise ValueError(f"Unknown mode: {mode}")

    if len(weight_shape) == 4:
        out_c, in_c, kh, kw = weight_shape
        flat_in = in_c * kh * kw
        if mode == "golden":
            flat = spiral_mask(out_c, flat_in, density, theta)
        elif mode == "random_sparse":
            flat = random_mask(out_c, flat_in, density, gen)
        else:
            raise ValueError(f"Unknown mode: {mode}")
        return flat.view(out_c, in_c, kh, kw)

    raise ValueError(f"Unsupported weight shape: {weight_shape}")

# -------------------------
# Layers
# -------------------------
class MaskedConv2d(nn.Module):
    def __init__(self, in_ch, out_ch, kernel_size, stride=1, padding=0, bias=True, mask=None):
        super().__init__()
        if isinstance(kernel_size, int):
            kh = kw = kernel_size
        else:
            kh, kw = kernel_size

        self.weight = nn.Parameter(torch.empty(out_ch, in_ch, kh, kw))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_ch)) if bias else None
        self.stride = stride
        self.padding = padding
        self.register_buffer("mask", mask.float())

    def forward(self, x):
        return F.conv2d(x, self.weight * self.mask, self.bias, stride=self.stride, padding=self.padding)

class MaskedLinear(nn.Module):
    def __init__(self, in_f, out_f, bias=True, mask=None):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(out_f, in_f))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_f)) if bias else None
        self.register_buffer("mask", mask.float())

    def forward(self, x):
        return F.linear(x, self.weight * self.mask, self.bias)

# -------------------------
# Models
# -------------------------
class TinyEdgeCNNMasked(nn.Module):
    def __init__(self, mode: str, density: float, seed: int, num_classes: int = 10):
        super().__init__()

        self.conv1 = MaskedConv2d(
            3, 16, kernel_size=3, stride=1, padding=1, bias=True,
            mask=make_weight_mask((16, 3, 3, 3), mode, density, seed + 1)
        )
        self.gn1 = nn.GroupNorm(4, 16)

        self.conv2 = MaskedConv2d(
            16, 32, kernel_size=3, stride=2, padding=1, bias=True,
            mask=make_weight_mask((32, 16, 3, 3), mode, density, seed + 2)
        )
        self.gn2 = nn.GroupNorm(8, 32)

        self.conv3 = MaskedConv2d(
            32, 64, kernel_size=3, stride=2, padding=1, bias=True,
            mask=make_weight_mask((64, 32, 3, 3), mode, density, seed + 3)
        )
        self.gn3 = nn.GroupNorm(8, 64)

        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.fc = MaskedLinear(
            64, num_classes, bias=True,
            mask=make_weight_mask((num_classes, 64), mode, density, seed + 999)
        )

    def forward(self, x):
        x = F.relu(self.gn1(self.conv1(x)), inplace=True)
        x = F.relu(self.gn2(self.conv2(x)), inplace=True)
        x = F.relu(self.gn3(self.conv3(x)), inplace=True)
        x = self.pool(x)
        x = torch.flatten(x, 1)
        x = self.fc(x)
        return x

class TinyEdgeCNNDense(nn.Module):
    def __init__(self, num_classes: int = 10):
        super().__init__()
        self.conv1 = nn.Conv2d(3, 16, kernel_size=3, stride=1, padding=1, bias=True)
        self.gn1 = nn.GroupNorm(4, 16)
        self.conv2 = nn.Conv2d(16, 32, kernel_size=3, stride=2, padding=1, bias=True)
        self.gn2 = nn.GroupNorm(8, 32)
        self.conv3 = nn.Conv2d(32, 64, kernel_size=3, stride=2, padding=1, bias=True)
        self.gn3 = nn.GroupNorm(8, 64)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.fc = nn.Linear(64, num_classes, bias=True)

    def forward(self, x):
        x = F.relu(self.gn1(self.conv1(x)), inplace=True)
        x = F.relu(self.gn2(self.conv2(x)), inplace=True)
        x = F.relu(self.gn3(self.conv3(x)), inplace=True)
        x = self.pool(x)
        x = torch.flatten(x, 1)
        x = self.fc(x)
        return x

# -------------------------
# Diagnostics
# -------------------------
def model_report(model):
    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    active_weights = 0
    total_weights = 0

    for m in model.modules():
        if isinstance(m, (MaskedConv2d, MaskedLinear)):
            active_weights += int(m.mask.sum().item())
            total_weights += m.weight.numel()
            if m.bias is not None:
                active_weights += m.bias.numel()
                total_weights += m.bias.numel()
        elif isinstance(m, (nn.Conv2d, nn.Linear)):
            active_weights += m.weight.numel()
            total_weights += m.weight.numel()
            if m.bias is not None:
                active_weights += m.bias.numel()
                total_weights += m.bias.numel()

    return {
        "trainable_params": trainable_params,
        "active_params_in_forward": active_weights,
        "total_possible_params": total_weights,
    }

def dead_neuron_diagnostic(model):
    rows = []
    total_dead = 0
    total_out = 0

    for name, module in model.named_modules():
        if hasattr(module, "mask"):
            mask = module.mask.detach().cpu()
            flat = mask.view(mask.size(0), -1)
            active_per_out = flat.sum(dim=1)
            dead = int((active_per_out == 0).sum().item())
            out_ch = int(mask.size(0))
            active_weights = int(mask.sum().item())
            possible_weights = int(mask.numel())

            rows.append({
                "layer": name,
                "dead": dead,
                "total_out": out_ch,
                "dead_pct": 100.0 * dead / out_ch if out_ch > 0 else 0.0,
                "active_weights": active_weights,
                "possible_weights": possible_weights,
                "sparsity_pct": 100.0 * (1.0 - active_weights / possible_weights) if possible_weights > 0 else 0.0,
            })
            total_dead += dead
            total_out += out_ch

    overall_dead_pct = 100.0 * total_dead / total_out if total_out > 0 else 0.0
    overall_sparsity_pct = None
    if rows:
        active = sum(r["active_weights"] for r in rows)
        possible = sum(r["possible_weights"] for r in rows)
        overall_sparsity_pct = 100.0 * (1.0 - active / possible) if possible > 0 else 0.0

    return rows, overall_dead_pct, overall_sparsity_pct

# -------------------------
# AMP helpers
# -------------------------
def amp_context():
    if USE_AMP:
        return torch.amp.autocast(device_type="cuda", enabled=True)
    return nullcontext()

criterion = nn.CrossEntropyLoss()

@torch.no_grad()
def evaluate(model, loader):
    model.eval()
    total_loss = 0.0
    correct = 0
    total = 0

    for x, y in loader:
        x = x.to(device, non_blocking=True)
        y = y.to(device, non_blocking=True)
        with amp_context():
            logits = model(x)
            loss = criterion(logits, y)

        total_loss += loss.item() * y.size(0)
        correct += (logits.argmax(dim=1) == y).sum().item()
        total += y.size(0)

    return total_loss / total, 100.0 * correct / total

# -------------------------
# Resume support
# -------------------------
results_cols = [
    "dataset", "density", "seed", "model", "step",
    "train_loss", "train_acc", "test_loss", "test_acc",
    "elapsed_sec", "dead_pct", "sparsity_pct"
]

def make_key(dataset, density, seed, model):
    return (str(dataset), round(float(density), 6), int(seed), str(model))

def save_csv(rows, path):
    if rows:
        pd.DataFrame(rows).to_csv(path, index=False)

results_rows = []
completed = set()

if os.path.exists(RESULTS_CSV):
    existing = pd.read_csv(RESULTS_CSV)
    existing = existing[[c for c in existing.columns if c in results_cols]].copy()

    if len(existing) > 0:
        keep_groups = []
        for key, g in existing.groupby(["dataset", "density", "seed", "model"]):
            if int(g["step"].max()) >= MAX_STEPS:
                keep_groups.append(g)
                completed.add(make_key(*key))
        existing = pd.concat(keep_groups, ignore_index=True) if keep_groups else existing.iloc[0:0].copy()
        results_rows = existing.to_dict("records")
        print(f"Resuming from {RESULTS_CSV}. Completed runs: {len(completed)}")
else:
    print("Starting fresh.")

# -------------------------
# Training
# -------------------------
def train_budget(model, train_loader, test_loader, name: str, dataset_name: str, density: float, seed: int, mode: str):
    model.to(device)
    optimizer = optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)
    scaler = torch.amp.GradScaler("cuda", enabled=USE_AMP)

    history = []
    start = time.time()

    step = 0
    model.train()
    pbar = tqdm(train_loader, desc=f"{name}", leave=False)

    for x, y in pbar:
        x = x.to(device, non_blocking=True)
        y = y.to(device, non_blocking=True)

        optimizer.zero_grad(set_to_none=True)

        with amp_context():
            logits = model(x)
            loss = criterion(logits, y)

        if USE_AMP:
            scaler.scale(loss).backward()
            scaler.step(optimizer)
            scaler.update()
        else:
            loss.backward()
            optimizer.step()

        step += 1
        batch_acc = (logits.argmax(dim=1) == y).float().mean().item() * 100.0

        pbar.set_postfix(step=step, loss=f"{loss.item():.4f}", batch_acc=f"{batch_acc:.2f}%")

        if step in CHECKPOINT_STEPS:
            test_loss, test_acc = evaluate(model, test_loader)
            elapsed_sec = time.time() - start

            row = {
                "dataset": dataset_name,
                "density": density,
                "seed": seed,
                "model": mode,
                "step": step,
                "train_loss": float(loss.item()),
                "train_acc": float(batch_acc),
                "test_loss": float(test_loss),
                "test_acc": float(test_acc),
                "elapsed_sec": float(elapsed_sec),
            }

            history.append(row)
            results_rows.append(row)
            save_csv(results_rows, RESULTS_CSV)

            print(
                f"✅ {name} | step {step:02d} | test={test_acc:.2f}% | "
                f"elapsed={elapsed_sec:.1f}s"
            )

        if step >= MAX_STEPS:
            break

    return pd.DataFrame(history)

# -------------------------
# Run
# -------------------------
start_time = time.time()
print("\nStarting CIFAR-10 edge microbenchmark...")

diagnostic_rows = []
example_masks = {}

for density in DENSITIES:
    for seed in SEEDS:
        for mode in MODES:
            key = make_key(DATASET_NAME, density, seed, mode)
            if key in completed:
                print(f"⏭️ Skipping completed run: {mode} | density={density:.2%} | seed={seed}")
                continue

            print(f"\n🚀 {DATASET_NAME} | {mode} | density={density:.2%} | seed={seed}")
            seed_everything(seed)

            if mode == "dense":
                model = TinyEdgeCNNDense(num_classes=10)
            else:
                model = TinyEdgeCNNMasked(mode=mode, density=density, seed=seed, num_classes=10)

            report = model_report(model)
            print(f"{mode} counts: {report}")

            diag_rows, dead_pct, sparsity_pct = dead_neuron_diagnostic(model)
            print(f"{mode} dead-neuron diagnostic:")
            for r in diag_rows:
                print(f"  - {r['layer']}: dead={r['dead']}/{r['total_out']} ({r['dead_pct']:.2f}%), sparsity={r['sparsity_pct']:.2f}%")
            print(f"{mode} overall dead neurons: {dead_pct:.2f}%")
            if sparsity_pct is not None:
                print(f"{mode} overall sparsity: {sparsity_pct:.2f}%")

            for r in diag_rows:
                diagnostic_rows.append({
                    "dataset": DATASET_NAME,
                    "density": density,
                    "seed": seed,
                    "model": mode,
                    "layer": r["layer"],
                    "dead": r["dead"],
                    "total_out": r["total_out"],
                    "dead_pct": r["dead_pct"],
                    "active_weights": r["active_weights"],
                    "possible_weights": r["possible_weights"],
                    "sparsity_pct": r["sparsity_pct"],
                    "overall_dead_pct": dead_pct,
                    "overall_sparsity_pct": sparsity_pct,
                })

            hist = train_budget(
                model=model,
                train_loader=train_loader,
                test_loader=test_loader,
                name=f"{mode} d={density:.0%} seed={seed}",
                dataset_name=DATASET_NAME,
                density=density,
                seed=seed,
                mode=mode,
            )

            if mode in ["golden", "random_sparse"] and seed == SEEDS[0] and hasattr(model, "conv1"):
                example_masks[(density, mode)] = model.conv1.mask.detach().cpu().clone()

            print(f"💾 Saved progress to {RESULTS_CSV}")

# Save dead diagnostics
dead_df = pd.DataFrame(diagnostic_rows)
dead_df.to_csv(DEAD_CSV, index=False)

# -------------------------
# Summary tables
# -------------------------
df = pd.DataFrame(results_rows)
df.to_csv(RESULTS_CSV, index=False)

finals = df[df["step"] == MAX_STEPS].copy()

summary = (
    finals.groupby(["dataset", "density", "model"])
    .agg(
        mean_test_acc=("test_acc", "mean"),
        std_test_acc=("test_acc", "std"),
        mean_train_acc=("train_acc", "mean"),
        std_train_acc=("train_acc", "std"),
        mean_elapsed_sec=("elapsed_sec", "mean"),
        std_elapsed_sec=("elapsed_sec", "std"),
    )
    .reset_index()
    .sort_values(["dataset", "density", "model"])
)

summary.to_csv(SUMMARY_CSV, index=False)

print("\n===== FINAL SUMMARY AT STEP 20 =====")
print(summary.to_string(index=False))

# paired gap table: golden - random_sparse
pair = finals.pivot_table(
    index=["dataset", "density", "seed"],
    columns="model",
    values="test_acc",
).reset_index()

if "golden" in pair.columns and "random_sparse" in pair.columns:
    pair["golden_minus_random"] = pair["golden"] - pair["random_sparse"]

    gap_summary = (
        pair.groupby(["dataset", "density"])["golden_minus_random"]
        .agg(["mean", "std"])
        .reset_index()
    )

    print("\n===== GOLDEN - RANDOM_SPARSE AT FINAL STEP =====")
    print(gap_summary.to_string(index=False))
else:
    gap_summary = pd.DataFrame()

dead_summary = (
    dead_df.groupby(["density", "model"])
    .agg(
        mean_dead_pct=("overall_dead_pct", "mean"),
        std_dead_pct=("overall_dead_pct", "std"),
        mean_sparsity_pct=("overall_sparsity_pct", "mean"),
        std_sparsity_pct=("overall_sparsity_pct", "std"),
    )
    .reset_index()
    .sort_values(["density", "model"])
)

print("\n===== DEAD-NEURON SUMMARY =====")
print(dead_summary.to_string(index=False))

# Save a compact checkpoint summary too
checkpoint_summary = (
    df[df["step"].isin(CHECKPOINT_STEPS)]
    .groupby(["density", "step", "model"])
    .agg(
        mean_test_acc=("test_acc", "mean"),
        std_test_acc=("test_acc", "std"),
    )
    .reset_index()
    .sort_values(["density", "step", "model"])
)

print("\n===== CHECKPOINT SUMMARY =====")
print(checkpoint_summary.to_string(index=False))

# -------------------------
# Separate figures per density
# -------------------------
for density in DENSITIES:
    sub = df[df["density"] == density].copy()
    final_sub = finals[finals["density"] == density].copy()
    csub = checkpoint_summary[checkpoint_summary["density"] == density].copy()

    # 1) Learning curves
    plt.figure(figsize=(9, 5))
    for mode in MODES:
        msub = sub[sub["model"] == mode].groupby("step").agg(
            mean_test_acc=("test_acc", "mean"),
            std_test_acc=("test_acc", "std"),
        ).reset_index().sort_values("step")
        if len(msub) == 0:
            continue
        plt.plot(msub["step"], msub["mean_test_acc"], marker="o", label=mode)
        std = msub["std_test_acc"].fillna(0)
        plt.fill_between(
            msub["step"],
            msub["mean_test_acc"] - std,
            msub["mean_test_acc"] + std,
            alpha=0.15,
        )
    plt.xlabel("Training step")
    plt.ylabel("Test accuracy (%)")
    plt.title(f"CIFAR-10 Edge Microbenchmark | density={density:.0%}")
    plt.legend()
    plt.tight_layout()
    plt.savefig(f"edge_curve_density_{int(density*100)}.png", dpi=200)
    plt.show()

    # 2) Final accuracy scatter
    plt.figure(figsize=(8, 5))
    for mode in MODES:
        vals = final_sub[final_sub["model"] == mode]["test_acc"]
        if len(vals) > 0:
            plt.scatter([mode] * len(vals), vals)
    plt.xlabel("Model")
    plt.ylabel("Final test accuracy (%)")
    plt.title(f"Final accuracy at step {MAX_STEPS} | density={density:.0%}")
    plt.tight_layout()
    plt.savefig(f"edge_final_scatter_density_{int(density*100)}.png", dpi=200)
    plt.show()

    # 3) Golden vs random gap per seed
    p = final_sub.pivot_table(index=["seed"], columns="model", values="test_acc").reset_index()
    if "golden" in p.columns and "random_sparse" in p.columns:
        p["golden_minus_random"] = p["golden"] - p["random_sparse"]
        plt.figure(figsize=(8, 5))
        plt.axhline(0, linestyle="--")
        plt.scatter(p["seed"], p["golden_minus_random"])
        plt.xlabel("Seed")
        plt.ylabel("Golden - Random (%)")
        plt.title(f"Paired gap at step {MAX_STEPS} | density={density:.0%}")
        plt.tight_layout()
        plt.savefig(f"edge_gap_density_{int(density*100)}.png", dpi=200)
        plt.show()

    # 4) Dead-neuron bar chart
    dsub = dead_summary[dead_summary["density"] == density].copy()
    plt.figure(figsize=(8, 5))
    plt.bar(dsub["model"], dsub["mean_dead_pct"])
    plt.ylabel("Mean dead-neuron %")
    plt.xlabel("Model")
    plt.title(f"Dead-neuron diagnostic | density={density:.0%}")
    plt.tight_layout()
    plt.savefig(f"edge_dead_density_{int(density*100)}.png", dpi=200)
    plt.show()

# Optional: visualize example masks
for density in DENSITIES:
    for mode in ["golden", "random_sparse"]:
        key = (density, mode)
        if key in example_masks:
            plt.figure(figsize=(9, 4))
            plt.imshow(example_masks[key].view(example_masks[key].shape[0], -1).numpy(), aspect="auto", cmap="viridis")
            plt.colorbar()
            plt.title(f"First conv mask | {mode} | density={density:.0%}")
            plt.tight_layout()
            plt.savefig(f"edge_mask_{mode}_density_{int(density*100)}.png", dpi=200)
            plt.show()

elapsed = time.time() - start_time
print(f"\nDone in {elapsed/60:.1f} minutes.")
print(f"Results saved to {RESULTS_CSV}")
print(f"Summary saved to {SUMMARY_CSV}")
print(f"Dead-neuron diagnostics saved to {DEAD_CSV}")

