# ============================================================
# Phyllotactic Sparsity: Aspect-Aware Ablation + Robustness
# MNIST + CIFAR-10 + CIFAR-100
#
# Compares:
#   - golden_original
#   - golden_aspect
#   - random_sparse
#   - dense
#
# Outputs:
#   - CSV logs
#   - per-dataset summary tables
#   - per-dataset combined figures
#   - mask visualizations
#   - dead-neuron / input-coverage diagnostics
#   - cross-dataset summary figure
#
# Notes:
#   - masks are enforced in every forward pass
#   - dense uses the same modules with mask=None
#   - random_sparse is seed-based and layer-specific
#   - robust eval uses Gaussian noise on normalized inputs
# ============================================================

