"""# CAUSAL COVERAGE EXPERIMENT (CPU SAFE)"""

# ============================================================
# CAUSAL COVERAGE EXPERIMENT (CPU SAFE)
# MNIST ONLY – tests if coverage CAUSES better accuracy
# ============================================================

import torch
import torch.nn as nn
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import numpy as np
import math
import random

device = torch.device("cpu")

# ============================================================
# CONFIG (SAFE FOR CPU – can increase later)
# ============================================================

SEEDS = [0, 1, 2, 3]   # increase to 5 if you want
DENSITY = 0.02
EPOCHS = 5
BATCH_SIZE = 128

MODES = ["random_sparse", "golden_original", "golden_coverage"]

# ============================================================
# DATA
# ============================================================

transform = transforms.Compose([
    transforms.ToTensor(),
])

trainset = torchvision.datasets.MNIST(root="./data", train=True, download=True, transform=transform)
testset = torchvision.datasets.MNIST(root="./data", train=False, download=True, transform=transform)

trainloader = torch.utils.data.DataLoader(trainset, batch_size=BATCH_SIZE, shuffle=True)
testloader = torch.utils.data.DataLoader(testset, batch_size=256, shuffle=False)

# ============================================================
# MASK FUNCTIONS
# ============================================================

def golden_angle():
    phi = (1 + 5 ** 0.5) / 2
    return 2 * np.pi * (1 - 1 / phi)

def exact_fill(mask, k):
    flat = mask.view(-1)
    current = int(flat.sum().item())
    if current < k:
        zeros = (flat == 0).nonzero(as_tuple=True)[0]
        flat[zeros[: (k - current)]] = 1.0
    return mask

def random_mask(out_f, in_f, density, seed):
    total = out_f * in_f
    k = int(total * density)
    gen = torch.Generator().manual_seed(seed)
    flat = torch.zeros(total)
    idx = torch.randperm(total, generator=gen)[:k]
    flat[idx] = 1.0
    return flat.view(out_f, in_f)

def spiral_mask_original(out_f, in_f, density):
    total = out_f * in_f
    k = int(total * density)
    theta = golden_angle()

    n = k * 5
    i = np.arange(n)
    r = np.sqrt(i / max(1, k))
    t = i * theta

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(int)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(int)

    mask = torch.zeros(out_f, in_f)
    for a, b in zip(xi, yi):
        if mask[a, b] == 0:
            mask[a, b] = 1.0
        if mask.sum() >= k:
            break

    return exact_fill(mask, k)

# 🔥 NEW: COVERAGE-FORCED
def spiral_mask_coverage(out_f, in_f, density, seed):
    total = out_f * in_f
    k = int(total * density)

    mask = torch.zeros(out_f, in_f)
    gen = torch.Generator().manual_seed(seed)

    # 1. force input coverage
    for j in range(min(in_f, k)):
        i = torch.randint(0, out_f, (1,), generator=gen).item()
        mask[i, j] = 1.0

    # 2. force no dead outputs
    for i in range(out_f):
        if mask[i].sum() == 0 and mask.sum() < k:
            j = torch.randint(0, in_f, (1,), generator=gen).item()
            mask[i, j] = 1.0

    # 3. fill remaining with spiral
    theta = golden_angle()
    remaining = k - int(mask.sum())

    if remaining > 0:
        n = remaining * 5
        idx = np.arange(n)
        r = np.sqrt(idx / max(1, remaining))
        t = idx * theta

        x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
        y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

        xi = np.clip(np.round(x), 0, out_f - 1).astype(int)
        yi = np.clip(np.round(y), 0, in_f - 1).astype(int)

        for a, b in zip(xi, yi):
            if mask[a, b] == 0:
                mask[a, b] = 1.0
                remaining -= 1
            if remaining <= 0:
                break

    return exact_fill(mask, k)

# ============================================================
# METRICS
# ============================================================

def compute_metrics(mask):
    m = mask.numpy()
    row = m.sum(axis=1)
    col = m.sum(axis=0)

    dead = (row == 0).mean() * 100
    coverage = (col > 0).mean() * 100

    return dead, coverage

# ============================================================
# MODEL
# ============================================================

class SparseLinear(nn.Module):
    def __init__(self, in_f, out_f, mask):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(out_f, in_f) * 0.01)
        self.bias = nn.Parameter(torch.zeros(out_f))
        self.mask = mask

    def forward(self, x):
        w = self.weight * self.mask
        return torch.matmul(x, w.t()) + self.bias

class Net(nn.Module):
    def __init__(self, mode, seed):
        super().__init__()

        if mode == "dense":
            self.fc1 = nn.Linear(784, 256)
            self.fc2 = nn.Linear(256, 10)
        else:
            if mode == "random_sparse":
                m1 = random_mask(256, 784, DENSITY, seed)
            elif mode == "golden_original":
                m1 = spiral_mask_original(256, 784, DENSITY)
            elif mode == "golden_coverage":
                m1 = spiral_mask_coverage(256, 784, DENSITY, seed)

            dead, cov = compute_metrics(m1)
            print(f"[{mode}] Dead={dead:.2f}% | Coverage={cov:.2f}%")

            self.fc1 = SparseLinear(784, 256, m1)
            self.fc2 = nn.Linear(256, 10)

    def forward(self, x):
        x = x.view(-1, 784)
        x = torch.relu(self.fc1(x))
        return self.fc2(x)

# ============================================================
# TRAIN / TEST
# ============================================================

def train_and_eval(mode, seed):
    torch.manual_seed(seed)
    np.random.seed(seed)
    random.seed(seed)

    net = Net(mode, seed).to(device)
    opt = optim.Adam(net.parameters(), lr=1e-3)
    loss_fn = nn.CrossEntropyLoss()

    for epoch in range(EPOCHS):
        net.train()
        for x, y in trainloader:
            x, y = x.to(device), y.to(device)
            opt.zero_grad()
            loss = loss_fn(net(x), y)
            loss.backward()
            opt.step()

    # test
    net.eval()
    correct = 0
    total = 0

    with torch.no_grad():
        for x, y in testloader:
            x, y = x.to(device), y.to(device)
            pred = net(x).argmax(1)
            correct += (pred == y).sum().item()
            total += y.size(0)

    return 100 * correct / total

# ============================================================
# MAIN LOOP
# ============================================================

results = {}

for mode in MODES:
    scores = []
    print(f"\n==== {mode} ====")
    for seed in SEEDS:
        acc = train_and_eval(mode, seed)
        print(f"Seed {seed}: {acc:.2f}%")
        scores.append(acc)

    mean = np.mean(scores)
    std = np.std(scores)

    results[mode] = (mean, std)

# ============================================================
# FINAL SUMMARY
# ============================================================

print("\n===== FINAL RESULT =====")
for k, (m, s) in results.items():
    print(f"{k:20s} : {m:.2f}% ± {s:.2f}")

# ============================================================
# UNIFORMITY / ENTROPY MECHANISM TEST (CPU SAFE)
# WHY golden > random when coverage is similar?
# ============================================================

import torch
import numpy as np
import math
import random

# ============================================================
# CONFIG
# ============================================================

SEEDS = [0, 1, 2, 3, 4]
DENSITY = 0.02

OUT_F = 256
IN_F = 784

MODES = ["random_sparse", "golden_original"]

# ============================================================
# MASK FUNCTIONS
# ============================================================

def golden_angle():
    phi = (1 + 5 ** 0.5) / 2
    return 2 * np.pi * (1 - 1 / phi)

def exact_fill(mask, k):
    flat = mask.reshape(-1)
    current = int(flat.sum())
    if current < k:
        zeros = np.where(flat == 0)[0]
        flat[zeros[: (k - current)]] = 1
    return flat.reshape(mask.shape)

def random_mask(out_f, in_f, density, seed):
    total = out_f * in_f
    k = int(total * density)
    rng = np.random.default_rng(seed)

    flat = np.zeros(total)
    idx = rng.permutation(total)[:k]
    flat[idx] = 1
    return flat.reshape(out_f, in_f)

def spiral_mask_original(out_f, in_f, density):
    total = out_f * in_f
    k = int(total * density)

    theta = golden_angle()

    n = k * 5
    i = np.arange(n)
    r = np.sqrt(i / max(1, k))
    t = i * theta

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(int)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(int)

    mask = np.zeros((out_f, in_f))
    for a, b in zip(xi, yi):
        if mask[a, b] == 0:
            mask[a, b] = 1
        if mask.sum() >= k:
            break

    return exact_fill(mask, k)

# ============================================================
# METRICS
# ============================================================

def entropy(p):
    p = p[p > 0]
    return -np.sum(p * np.log(p + 1e-12))

def compute_metrics(mask):
    row = mask.sum(axis=1)
    col = mask.sum(axis=0)

    # Normalize distributions
    row_p = row / row.sum()
    col_p = col / col.sum()

    # Entropy
    row_entropy = entropy(row_p)
    col_entropy = entropy(col_p)

    # Coefficient of variation (std / mean)
    row_cv = np.std(row) / (np.mean(row) + 1e-8)
    col_cv = np.std(col) / (np.mean(col) + 1e-8)

    # Coverage
    coverage = (col > 0).mean() * 100

    return {
        "row_entropy": row_entropy,
        "col_entropy": col_entropy,
        "row_cv": row_cv,
        "col_cv": col_cv,
        "coverage": coverage
    }

# ============================================================
# MAIN LOOP
# ============================================================

results = {}

for mode in MODES:
    print(f"\n==== {mode} ====")

    all_metrics = []

    for seed in SEEDS:
        if mode == "random_sparse":
            mask = random_mask(OUT_F, IN_F, DENSITY, seed)
        else:
            mask = spiral_mask_original(OUT_F, IN_F, DENSITY)

        metrics = compute_metrics(mask)
        all_metrics.append(metrics)

        print(f"Seed {seed}: "
              f"RowEnt={metrics['row_entropy']:.4f}, "
              f"ColEnt={metrics['col_entropy']:.4f}, "
              f"RowCV={metrics['row_cv']:.4f}, "
              f"ColCV={metrics['col_cv']:.4f}, "
              f"Cov={metrics['coverage']:.2f}%")

    # Average
    avg = {
        k: np.mean([m[k] for m in all_metrics])
        for k in all_metrics[0]
    }

    results[mode] = avg

# ============================================================
# FINAL SUMMARY
# ============================================================

print("\n===== FINAL SUMMARY =====")
for mode, m in results.items():
    print(f"\n{mode}")
    for k, v in m.items():
        print(f"{k:15s}: {v:.4f}")

"""#   - dense, random_sparse, golden_original,magnitude_pruned compare on mnist 2% same seed"""

# ============================================================
# FINAL FAIR COMPARISON RUN
# MNIST 2% | same seeds | rerun golden inside this script
# Modes:
#   - dense
#   - random_sparse
#   - golden_original
#   - magnitude_pruned
#
# Goal:
#   1) Re-run golden fairly in the same script
#   2) Add magnitude pruning as the strongest baseline
#   3) Keep the setup identical across seeds
#   4) Save CSV + summary + one clean figure
# ============================================================

import os
import math
import time
import random
from contextlib import nullcontext

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

from tqdm.auto import tqdm

try:
    from scipy import stats
except Exception:
    stats = None

# -------------------------
# Device
# -------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)
if device.type == "cuda":
    print("🔥 GPU:", torch.cuda.get_device_name(0))
    torch.backends.cudnn.benchmark = True

try:
    torch.set_float32_matmul_precision("high")
except Exception:
    pass

# -------------------------
# Config
# -------------------------
DATASET_NAME = "MNIST"
DENSITY = 0.02

SEEDS = [0, 1, 2, 3, 4]

SPARSE_EPOCHS = 5
PRUNE_PRETRAIN_EPOCHS = 3
PRUNE_FINETUNE_EPOCHS = 2

BATCH_SIZE_TRAIN = 128
BATCH_SIZE_TEST = 256

LR = 1e-3
WEIGHT_DECAY = 5e-4

RESULTS_CSV = "mnist_2pct_final_fair_results.csv"
SUMMARY_CSV = "mnist_2pct_final_fair_summary.csv"
FIG_PATH = "mnist_2pct_final_fair_comparison.png"

MODES = ["dense", "random_sparse", "golden_original", "magnitude_pruned"]

# -------------------------
# Reproducibility
# -------------------------
def seed_everything(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -------------------------
# Data
# -------------------------
MNIST_MEAN = (0.1307,)
MNIST_STD = (0.3081,)

transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize(MNIST_MEAN, MNIST_STD),
])

trainset = torchvision.datasets.MNIST(
    root="./data", train=True, download=True, transform=transform
)
testset = torchvision.datasets.MNIST(
    root="./data", train=False, download=True, transform=transform
)

def make_loaders(seed: int):
    g = torch.Generator().manual_seed(seed)

    train_loader = torch.utils.data.DataLoader(
        trainset,
        batch_size=BATCH_SIZE_TRAIN,
        shuffle=True,
        num_workers=0,
        pin_memory=(device.type == "cuda"),
        generator=g,
    )

    test_loader = torch.utils.data.DataLoader(
        testset,
        batch_size=BATCH_SIZE_TEST,
        shuffle=False,
        num_workers=0,
        pin_memory=(device.type == "cuda"),
    )

    return train_loader, test_loader

# -------------------------
# Mask helpers
# -------------------------
def golden_angle():
    phi = (1 + 5 ** 0.5) / 2
    return 2 * np.pi * (1 - 1 / phi)

def exact_fill(mask: torch.Tensor, k: int):
    flat = mask.view(-1)
    current = int(flat.sum().item())
    if current >= k:
        return mask
    zeros = (flat == 0).nonzero(as_tuple=True)[0]
    flat[zeros[: (k - current)]] = 1.0
    return mask

def random_mask(out_f: int, in_f: int, density: float, seed: int):
    total = out_f * in_f
    k = max(1, int(round(total * density)))
    gen = torch.Generator().manual_seed(seed)
    flat = torch.zeros(total, dtype=torch.float32)
    idx = torch.randperm(total, generator=gen)[:k]
    flat[idx] = 1.0
    return flat.view(out_f, in_f)

def spiral_mask_original(out_f: int, in_f: int, density: float):
    total = out_f * in_f
    k = max(1, int(round(total * density)))
    theta = golden_angle()

    n = max(k * 5, k + 32)
    i = np.arange(n, dtype=np.float64)

    r = np.sqrt(i / max(1, k))
    t = i * theta

    x = (0.5 + 0.5 * r * np.cos(t)) * (out_f - 1)
    y = (0.5 + 0.5 * r * np.sin(t)) * (in_f - 1)

    xi = np.clip(np.round(x), 0, out_f - 1).astype(np.int64)
    yi = np.clip(np.round(y), 0, in_f - 1).astype(np.int64)

    mask = torch.zeros(out_f, in_f, dtype=torch.float32)
    for a, b in zip(xi, yi):
        if mask[a, b] == 0:
            mask[a, b] = 1.0
        if int(mask.sum().item()) >= k:
            break

    return exact_fill(mask, k)

def make_layer_mask(shape, mode: str, density: float, seed: int):
    out_f, in_f = shape
    if mode == "random_sparse":
        return random_mask(out_f, in_f, density, seed)
    if mode == "golden_original":
        return spiral_mask_original(out_f, in_f, density)
    raise ValueError(f"Unsupported sparse mode: {mode}")

def global_magnitude_masks_from_dense(model: nn.Module, density: float):
    """
    Exact global top-k pruning across all weight matrices.
    Biases are not pruned.
    """
    weight_tensors = [
        model.fc1.weight.detach().abs(),
        model.fc2.weight.detach().abs(),
        model.fc3.weight.detach().abs(),
    ]

    flat = torch.cat([w.reshape(-1) for w in weight_tensors], dim=0)
    total = flat.numel()
    k = max(1, int(round(total * density)))

    keep_idx = torch.topk(flat, k=k, largest=True, sorted=False).indices
    global_mask = torch.zeros_like(flat)
    global_mask[keep_idx] = 1.0

    masks = {}
    offset = 0
    for name, w in zip(["fc1", "fc2", "fc3"], weight_tensors):
        n = w.numel()
        masks[name] = global_mask[offset:offset + n].view_as(w).clone()
        offset += n

    return masks

# -------------------------
# Layers
# -------------------------
class MaskedLinear(nn.Module):
    def __init__(self, in_f, out_f, mask=None, bias=True):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(out_f, in_f))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(out_f)) if bias else None
        self.register_buffer("mask", mask.float())

    def forward(self, x):
        return F.linear(x, self.weight * self.mask, self.bias)

# -------------------------
# Models
# -------------------------
class DenseMLP(nn.Module):
    def __init__(self, num_classes=10):
        super().__init__()
        self.fc1 = nn.Linear(784, 256)
        self.fc2 = nn.Linear(256, 128)
        self.fc3 = nn.Linear(128, num_classes)

    def forward(self, x):
        x = x.view(x.size(0), -1)
        x = F.relu(self.fc1(x), inplace=True)
        x = F.relu(self.fc2(x), inplace=True)
        return self.fc3(x)

class SparseMLP(nn.Module):
    def __init__(self, mode: str, density: float, seed: int, num_classes=10):
        super().__init__()

        m1 = make_layer_mask((256, 784), mode, density, seed + 1)
        m2 = make_layer_mask((128, 256), mode, density, seed + 2)
        m3 = make_layer_mask((num_classes, 128), mode, density, seed + 3)

        self.fc1 = MaskedLinear(784, 256, mask=m1, bias=True)
        self.fc2 = MaskedLinear(256, 128, mask=m2, bias=True)
        self.fc3 = MaskedLinear(128, num_classes, mask=m3, bias=True)

    def forward(self, x):
        x = x.view(x.size(0), -1)
        x = F.relu(self.fc1(x), inplace=True)
        x = F.relu(self.fc2(x), inplace=True)
        return self.fc3(x)

def copy_dense_to_sparse(dense_model: DenseMLP, sparse_model: SparseMLP):
    sparse_model.fc1.weight.data.copy_(dense_model.fc1.weight.data)
    sparse_model.fc2.weight.data.copy_(dense_model.fc2.weight.data)
    sparse_model.fc3.weight.data.copy_(dense_model.fc3.weight.data)

    sparse_model.fc1.bias.data.copy_(dense_model.fc1.bias.data)
    sparse_model.fc2.bias.data.copy_(dense_model.fc2.bias.data)
    sparse_model.fc3.bias.data.copy_(dense_model.fc3.bias.data)

    sparse_model.fc1.weight.data.mul_(sparse_model.fc1.mask)
    sparse_model.fc2.weight.data.mul_(sparse_model.fc2.mask)
    sparse_model.fc3.weight.data.mul_(sparse_model.fc3.mask)

# -------------------------
# Diagnostics
# -------------------------
def model_report(model):
    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    active_weights = 0
    total_weights = 0

    for m in model.modules():
        if isinstance(m, MaskedLinear):
            active_weights += int(m.mask.sum().item())
            total_weights += m.weight.numel()
            if m.bias is not None:
                active_weights += m.bias.numel()
                total_weights += m.bias.numel()
        elif isinstance(m, nn.Linear):
            active_weights += m.weight.numel()
            total_weights += m.weight.numel()
            if m.bias is not None:
                active_weights += m.bias.numel()
                total_weights += m.bias.numel()

    return {
        "trainable_params": trainable_params,
        "active_params_in_forward": active_weights,
        "total_possible_params": total_weights,
    }

def mask_diagnostics(model):
    rows = []
    for name, module in model.named_modules():
        if hasattr(module, "mask"):
            mask = module.mask.detach().cpu()
            flat = mask.view(mask.size(0), -1)
            active_per_out = flat.sum(dim=1)
            dead = int((active_per_out == 0).sum().item())
            out_ch = int(mask.size(0))
            active_weights = int(mask.sum().item())
            possible_weights = int(mask.numel())
            rows.append({
                "layer": name,
                "dead": dead,
                "total_out": out_ch,
                "dead_pct": 100.0 * dead / out_ch if out_ch > 0 else 0.0,
                "active_weights": active_weights,
                "possible_weights": possible_weights,
                "sparsity_pct": 100.0 * (1.0 - active_weights / possible_weights) if possible_weights > 0 else 0.0,
            })
    return rows

# -------------------------
# Train / Eval
# -------------------------
criterion = nn.CrossEntropyLoss()

@torch.no_grad()
def evaluate(model, loader):
    model.eval()
    total_loss = 0.0
    correct = 0
    total = 0

    for x, y in loader:
        x = x.to(device, non_blocking=True)
        y = y.to(device, non_blocking=True)
        logits = model(x)
        loss = criterion(logits, y)
        total_loss += loss.item() * y.size(0)
        correct += (logits.argmax(dim=1) == y).sum().item()
        total += y.size(0)

    return total_loss / total, 100.0 * correct / total

def train_epochs(model, train_loader, test_loader, epochs: int, lr: float, weight_decay: float):
    optimizer = torch.optim.Adam(model.parameters(), lr=lr, weight_decay=weight_decay)
    history = []

    model.to(device)
    start = time.time()

    for epoch in range(1, epochs + 1):
        model.train()
        running_loss = 0.0
        correct = 0
        total = 0

        pbar = tqdm(train_loader, desc=f"epoch {epoch}/{epochs}", leave=False)
        for x, y in pbar:
            x = x.to(device, non_blocking=True)
            y = y.to(device, non_blocking=True)

            optimizer.zero_grad(set_to_none=True)
            logits = model(x)
            loss = criterion(logits, y)
            loss.backward()
            optimizer.step()

            running_loss += loss.item() * y.size(0)
            correct += (logits.argmax(dim=1) == y).sum().item()
            total += y.size(0)

            pbar.set_postfix(
                train_acc=f"{100.0 * correct / total:.2f}%",
                loss=f"{running_loss / total:.4f}",
            )

        train_loss = running_loss / total
        train_acc = 100.0 * correct / total
        test_loss, test_acc = evaluate(model, test_loader)

        history.append({
            "epoch": epoch,
            "train_loss": train_loss,
            "train_acc": train_acc,
            "test_loss": test_loss,
            "test_acc": test_acc,
            "elapsed_sec": time.time() - start,
        })

    return history

# -------------------------
# Run
# -------------------------
start_time = time.time()
print("\nStarting final fair MNIST 2% comparison...")

results_rows = []

for seed in SEEDS:
    print(f"\n================ SEED {seed} ================")
    seed_everything(seed)
    train_loader, test_loader = make_loaders(seed)

    # 1) Dense
    print("\n--- dense ---")
    dense = DenseMLP(num_classes=10)
    print("counts:", model_report(dense))
    dense_hist = train_epochs(dense, train_loader, test_loader, SPARSE_EPOCHS, LR, WEIGHT_DECAY)
    dense_final = dense_hist[-1]
    results_rows.append({
        "dataset": DATASET_NAME,
        "density": DENSITY,
        "seed": seed,
        "model": "dense",
        **dense_final,
    })
    print(f"✅ dense | final test={dense_final['test_acc']:.2f}%")

    # 2) Random sparse
    print("\n--- random_sparse ---")
    seed_everything(seed)
    train_loader, test_loader = make_loaders(seed)
    random_model = SparseMLP("random_sparse", DENSITY, seed, num_classes=10)
    print("counts:", model_report(random_model))
    print("diagnostics:", mask_diagnostics(random_model))
    random_hist = train_epochs(random_model, train_loader, test_loader, SPARSE_EPOCHS, LR, WEIGHT_DECAY)
    random_final = random_hist[-1]
    results_rows.append({
        "dataset": DATASET_NAME,
        "density": DENSITY,
        "seed": seed,
        "model": "random_sparse",
        **random_final,
    })
    print(f"✅ random_sparse | final test={random_final['test_acc']:.2f}%")

    # 3) Golden original
    print("\n--- golden_original ---")
    seed_everything(seed)
    train_loader, test_loader = make_loaders(seed)
    golden_model = SparseMLP("golden_original", DENSITY, seed, num_classes=10)
    print("counts:", model_report(golden_model))
    print("diagnostics:", mask_diagnostics(golden_model))
    golden_hist = train_epochs(golden_model, train_loader, test_loader, SPARSE_EPOCHS, LR, WEIGHT_DECAY)
    golden_final = golden_hist[-1]
    results_rows.append({
        "dataset": DATASET_NAME,
        "density": DENSITY,
        "seed": seed,
        "model": "golden_original",
        **golden_final,
    })
    print(f"✅ golden_original | final test={golden_final['test_acc']:.2f}%")

    # 4) Magnitude-pruned
    #    Stage A: dense pretrain on the same seed / same loaders
    #    Stage B: prune globally to the same density
    #    Stage C: finetune the sparse model
    print("\n--- magnitude_pruned ---")
    seed_everything(seed)
    train_loader, test_loader = make_loaders(seed)

    dense_for_prune = DenseMLP(num_classes=10)
    print("pretrain counts:", model_report(dense_for_prune))
    pre_hist = train_epochs(
        dense_for_prune,
        train_loader,
        test_loader,
        PRUNE_PRETRAIN_EPOCHS,
        LR,
        WEIGHT_DECAY,
    )
    pre_final = pre_hist[-1]

    masks = global_magnitude_masks_from_dense(dense_for_prune, DENSITY)
    pruned_model = SparseMLP("golden_original", DENSITY, seed, num_classes=10)
    pruned_model.fc1.mask.data.copy_(masks["fc1"].to(pruned_model.fc1.mask.device))
    pruned_model.fc2.mask.data.copy_(masks["fc2"].to(pruned_model.fc2.mask.device))
    pruned_model.fc3.mask.data.copy_(masks["fc3"].to(pruned_model.fc3.mask.device))
    copy_dense_to_sparse(dense_for_prune, pruned_model)

    print("pruned counts:", model_report(pruned_model))
    print("pruned diagnostics:", mask_diagnostics(pruned_model))

    prune_hist = train_epochs(
        pruned_model,
        train_loader,
        test_loader,
        PRUNE_FINETUNE_EPOCHS,
        LR,
        WEIGHT_DECAY,
    )
    prune_final = prune_hist[-1]

    results_rows.append({
        "dataset": DATASET_NAME,
        "density": DENSITY,
        "seed": seed,
        "model": "magnitude_pruned",
        "pretrain_test_acc": pre_final["test_acc"],
        "pretrain_test_loss": pre_final["test_loss"],
        "postprune_train_loss": prune_final["train_loss"],
        "postprune_train_acc": prune_final["train_acc"],
        "test_loss": prune_final["test_loss"],
        "test_acc": prune_final["test_acc"],
        "elapsed_sec": prune_final["elapsed_sec"],
    })
    print(f"✅ magnitude_pruned | pretrain test={pre_final['test_acc']:.2f}% | final test={prune_final['test_acc']:.2f}%")

# -------------------------
# Save rows
# -------------------------
df = pd.DataFrame(results_rows)
df.to_csv(RESULTS_CSV, index=False)

# -------------------------
# Final summary
# -------------------------
finals = df.copy()

summary = (
    finals.groupby(["dataset", "density", "model"])
    .agg(
        mean_test_acc=("test_acc", "mean"),
        std_test_acc=("test_acc", "std"),
        mean_train_acc=("train_acc", "mean"),
        std_train_acc=("train_acc", "std"),
        mean_elapsed_sec=("elapsed_sec", "mean"),
        std_elapsed_sec=("elapsed_sec", "std"),
    )
    .reset_index()
    .sort_values(["model"])
)

summary.to_csv(SUMMARY_CSV, index=False)

print("\n===== FINAL SUMMARY =====")
print(summary.to_string(index=False))

# -------------------------
# Paired gaps
# -------------------------
pair = finals.pivot_table(index=["seed"], columns="model", values="test_acc").reset_index()

def paired_gap(a: str, b: str):
    if a not in pair.columns or b not in pair.columns:
        return None
    gap = pair[a] - pair[b]
    out = {
        "comparison": f"{a} - {b}",
        "mean_gap": float(gap.mean()),
        "std_gap": float(gap.std(ddof=1)) if len(gap) > 1 else float("nan"),
    }
    if stats is not None and len(gap) > 1:
        t = stats.ttest_rel(pair[a], pair[b], nan_policy="omit")
        out["t_stat"] = float(t.statistic)
        out["p_value"] = float(t.pvalue)
        sd = gap.std(ddof=1)
        out["cohens_d"] = float(gap.mean() / sd) if sd > 0 else float("nan")
    else:
        out["t_stat"] = float("nan")
        out["p_value"] = float("nan")
        out["cohens_d"] = float("nan")
    return out

gap_rows = [
    paired_gap("golden_original", "random_sparse"),
    paired_gap("golden_original", "magnitude_pruned"),
    paired_gap("magnitude_pruned", "random_sparse"),
]
gap_rows = [g for g in gap_rows if g is not None]
gap_df = pd.DataFrame(gap_rows)

print("\n===== PAIRED GAPS =====")
print(gap_df.to_string(index=False))

# -------------------------
# Figure
# -------------------------
display_name = {
    "dense": "Dense",
    "random_sparse": "Random sparse",
    "golden_original": "Golden original",
    "magnitude_pruned": "Magnitude pruned",
}

order = ["dense", "random_sparse", "golden_original", "magnitude_pruned"]
plot_df = summary.set_index("model").reindex(order).reset_index()

plt.figure(figsize=(10, 6))
x = np.arange(len(order))
plt.bar(
    x,
    plot_df["mean_test_acc"],
    yerr=plot_df["std_test_acc"].fillna(0),
    capsize=4,
)
plt.xticks(x, [display_name[m] for m in order], rotation=20)
plt.ylabel("Final test accuracy (%)")
plt.title("MNIST 2% final fair comparison")
plt.tight_layout()
plt.savefig(FIG_PATH, dpi=220, bbox_inches="tight")
plt.show()

elapsed = time.time() - start_time
print(f"\nDone in {elapsed/60:.1f} minutes.")
print(f"Saved: {RESULTS_CSV}")
print(f"Saved: {SUMMARY_CSV}")
print(f"Saved: {FIG_PATH}")
